{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-975b2fc0d7f2264e","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"Pipeline state machine for the thin dispatcher.\n3\t\n4\tPhase tracking, config, and transition logic for epic-decompose.\n5\t\n6\tUsage:\n7\t    python3 scripts/pipeline_state.py init [--batch-size N] [--headless]\n8\t    python3 scripts/pipeline_state.py get-phase\n9\t    python3 scripts/pipeline_state.py set-phase <PHASE>\n10\t    python3 scripts/pipeline_state.py get-phase-config\n11\t    python3 scripts/pipeline_state.py run-phase\n12\t    python3 scripts/pipeline_state.py advance [--dry-run]\n13\t    python3 scripts/pipeline_state.py set-wave <IDs>\n14\t    python3 scripts/pipeline_state.py set key=value ...\n15\t    python3 scripts/pipeline_state.py get <key>\n16\t    python3 scripts/pipeline_state.py status\n17\t    python3 scripts/pipeline_state.py diagnose\n18\t\"\"\"\n19\t\n20\timport argparse\n21\timport glob\n22\timport os\n23\timport shutil\n24\timport subprocess\n25\timport sys\n26\tfrom datetime import datetime, timezone\n27\t\n28\timport yaml\n29\t\n30\tSTATE_FILE = \"tmp/pipeline-state.yaml\"\n31\tWAVE_IDS_FILE = \"tmp/pipeline-wave-ids.txt\"\n32\tDISPATCH_MARKER = \"tmp/.dispatch-marker\"\n33\t\n34\tMAX_NEXT_ACTION_ITERATIONS = 50\n35\t\n36\t\n37\t# ---------- YAML block-scalar dumper (scoped) ----------\n38\t\n39\tdef _str_representer(dumper, data):\n40\t    if '\\n' in data:\n41\t        return dumper.represent_scalar(\n42\t            'tag:yaml.org,2002:str', data, style='|')\n43\t    return dumper.represent_scalar('tag:yaml.org,2002:str', data)\n44\t\n45\t\n46\tclass _BlockDumper(yaml.Dumper):\n47\t    pass\n48\t\n49\t\n50\t_BlockDumper.add_representer(str, _str_representer)\n51\t\n52\t# ---------- Phase enum ----------\n53\t\n54\tPHASES = [\n55\t    \"BATCH_START\", \"FETCH\", \"DECOMPOSE\", \"REVIEW_DECOMP\",\n56\t    \"REVISE_DECOMP\",\n57\t    \"RE_REVIEW_CHECK\", \"RE_REVIEW\", \"REVISE_CHECK\", \"RE_REVISE\",\n58\t    \"BATCH_DONE\", \"ERROR_COLLECT\",\n59\t    \"REPORT\", \"DONE\",\n60\t]\n61\t\n62\t# ---------- Phase config ----------\n63\t\n64\tPHASE_CONFIG = {\n65\t    \"BATCH_START\": {\"type\": \"noop\"},\n66\t    \"FETCH\": {\n67\t        \"type\": \"agent\",\n68\t        \"prompt\": \"skills/epic-decompose/prompts/fetch-agent.md\",\n69\t        \"ids_file\": \"tmp/pipeline-active-ids.txt\",\n70\t        \"poll_phase\": \"fetch\",\n71\t        \"vars\": {\"ID\": \"{ID}\"},\n72\t    },\n73\t    \"DECOMPOSE\": {\n74\t        \"type\": \"agent\",\n75\t        \"prompt\": \"skills/epic-decompose/prompts/decompose-agent.md\",\n76\t        \"ids_file\": \"tmp/pipeline-active-ids.txt\",\n77\t        \"poll_phase\": \"decompose\",\n78\t        \"vars\": {\"ID\": \"{ID}\"},\n79\t    },\n80\t    \"REVIEW_DECOMP\": {\n81\t        \"type\": \"agent\",\n82\t        \"prompt\": \"skills/epic-decompose/prompts/review-agent.md\",\n83\t        \"ids_file\": \"tmp/pipeline-active-ids.txt\",\n84\t        \"poll_phase\": \"review_decomp\",\n85\t        \"vars\": {\"ID\": \"{ID}\"},\n86\t    },\n87\t    \"REVISE_DECOMP\": {\n88\t        \"type\": \"agent\",\n89\t        \"prompt\": \"skills/epic-decompose/prompts/revise-agent.md\",\n90\t        \"ids_file\": \"tmp/pipeline-active-ids.txt\",\n91\t        \"poll_phase\": \"revise_decomp\",\n92\t        \"vars\": {\"ID\": \"{ID}\"},\n93\t    },\n94\t    \"RE_REVIEW_CHECK\": {\"type\": \"noop\"},\n95\t    \"RE_REVIEW\": {\n96\t        \"type\": \"agent\",\n97\t        \"prompt\": \"skills/epic-decompose/prompts/review-agent.md\",\n98\t        \"ids_file\": \"tmp/pipeline-revise-ids.txt\",\n99\t        \"poll_phase\": \"review_decomp\",\n100\t        \"vars\": {\"ID\": \"{ID}\"},\n101\t    },\n102\t    \"REVISE_CHECK\": {\"type\": \"noop\"},\n103\t    \"RE_REVISE\": {\n104\t        \"type\": \"agent\",\n105\t        \"prompt\": \"skills/epic-decompose/prompts/revise-agent.md\",\n106\t        \"ids_file\": \"tmp/pipeline-revise-ids.txt\",\n107\t        \"poll_phase\": \"revise_decomp\",\n108\t        \"vars\": {\"ID\": \"{ID}\"},\n109\t    },\n110\t\n111\t    # --- Batch control + retry ---\n112\t    \"BATCH_DONE\": {\"type\": \"noop\"},\n113\t    \"ERROR_COLLECT\": {\n114\t        \"type\": \"script\",\n115\t        \"command\": \"python3 scripts/error_collect.py\",\n116\t    },\n117\t\n118\t    # --- Terminal ---\n119\t    \"REPORT\": {\n120\t        \"type\": \"script\",\n121\t        \"command\": (\"python3 scripts/generate_run_report.py\"\n122\t                    \" --start-time {start_time}\"\n123\t                    \" --batch-size {batch_size}\"),\n124\t    },\n125\t}\n126\t\n127\t# ---------- State helpers ----------\n128\t\n129\t\n130\tdef _load_state():\n131\t    if not os.path.exists(STATE_FILE):\n132\t        print(f\"State file not found: {STATE_FILE}\", file=sys.stderr)\n133\t        sys.exit(1)\n134\t    with open(STATE_FILE) as f:\n135\t        return yaml.safe_load(f)\n136\t\n137\t\n138\tdef _save_state(state):\n139\t    os.makedirs(os.path.dirname(STATE_FILE), exist_ok=True)\n140\t    with open(STATE_FILE, \"w\") as f:\n141\t        yaml.dump(state, f, default_flow_style=False, sort_keys=False)\n142\t\n143\t\n144\tdef _read_ids(path):\n145\t    if not os.path.exists(path):\n146\t        return []\n147\t    with open(path) as f:\n148\t        return [line.strip() for line in f if line.strip()]\n149\t\n150\t\n151\tdef _write_ids(path, ids):\n152\t    os.makedirs(os.path.dirname(path) or \"tmp\", exist_ok=True)\n153\t    with open(path, \"w\") as f:\n154\t        for id_ in ids:\n155\t            f.write(f\"{id_}\\n\")\n156\t\n157\t\n158\tdef _copy_ids(src, dst):\n159\t    os.makedirs(os.path.dirname(dst) or \"tmp\", exist_ok=True)\n160\t    shutil.copy2(src, dst)\n161\t\n162\t\n163\tdef _reset_revised_flag(decomp_path):\n164\t    \"\"\"Remove ``revised`` key from decomposition frontmatter.\n165\t\n166\t    The revise_decomp completion poller treats *any* non-None value\n167\t    (including False) as \"completed\".  Removing the key forces it back to\n168\t    \"pending\" so the revise agent is actually launched.\n169\t    \"\"\"\n170\t    from artifact_utils import read_frontmatter\n171\t    data, body = read_frontmatter(decomp_path)\n172\t    if data and \"revised\" in data:\n173\t        del data[\"revised\"]\n174\t        with open(decomp_path, \"w\") as f:\n175\t            f.write(\"---\\n\")\n176\t            f.write(yaml.dump(data, default_flow_style=False, sort_keys=False))\n177\t            f.write(\"---\\n\")\n178\t            f.write(body)\n179\t\n180\t\n181\tdef _run_script(cmd):\n182\t    result = subprocess.run(\n183\t        cmd, shell=True, capture_output=True, text=True)\n184\t    if result.returncode != 0:\n185\t        print(\"Script failed (exit code \"\n186\t              f\"{result.returncode})\", file=sys.stderr)\n187\t        if result.stderr:\n188\t            print(result.stderr, file=sys.stderr)\n189\t        sys.exit(1)\n190\t    return result.stdout.strip()\n191\t\n192\t\n193\tdef _compute_ai_scores(ids_file):\n194\t    \"\"\"Compute AI implementability scores from signal values in epic frontmatter.\"\"\"\n195\t    ids = _read_ids(ids_file)\n196\t    if not ids:\n197\t        return\n198\t    cmd = f\"python3 scripts/compute_ai_scores.py {' '.join(ids)}\"\n199\t    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)\n200\t    if result.stderr:\n201\t        print(result.stderr, file=sys.stderr)\n202\t\n203\t\n204\t# ---------- Transition logic ----------\n205\t\n206\tMAIN_SEQUENCE = [\"FETCH\", \"DECOMPOSE\", \"REVIEW_DECOMP\"]\n207\t\n208\t\n209\tdef advance(state, dry_run=False):\n210\t    \"\"\"Compute and apply the next phase transition.\n211\t\n212\t    Returns (next_phase, summary_line).\n213\t    \"\"\"\n214\t    phase = state[\"phase\"]\n215\t\n216\t    # --- BATCH_START: reset counters, populate active IDs ---\n217\t    if phase == \"BATCH_START\":\n218\t        batch = state.get(\"batch\", 0) + 1\n219\t        if not dry_run:\n220\t            state[\"batch\"] = batch\n221\t            batch_file = f\"tmp/pipeline-batch-{batch}-ids.txt\"\n222\t            _copy_ids(batch_file, \"tmp/pipeline-active-ids.txt\")\n223\t        return \"FETCH\", f\"BATCH_START → FETCH: batch={batch}\"\n224\t\n225\t    # --- Linear main sequence ---\n226\t    if phase in MAIN_SEQUENCE[:-1]:\n227\t        nxt = MAIN_SEQUENCE[MAIN_SEQUENCE.index(phase) + 1]\n228\t        if phase == \"DECOMPOSE\" and not dry_run:\n229\t            _compute_ai_scores(\"tmp/pipeline-active-ids.txt\")\n230\t        return nxt, f\"{phase} → {nxt}\"\n231\t\n232\t    # --- REVIEW_DECOMP → REVISE_DECOMP (unconditional first revision) ---\n233\t    if phase == \"REVIEW_DECOMP\":\n234\t        if not dry_run:\n235\t            # Clear the ``revised`` default so the poller sees IDs as pending.\n236\t            # The schema sets revised: false on creation, but the poller\n237\t            # treats any non-None value as \"completed\".\n238\t            for strat_id in _read_ids(\"tmp/pipeline-active-ids.txt\"):\n239\t                decomp = f\"artifacts/epic-tasks/{strat_id}-decomposition.md\"\n240\t                if os.path.exists(decomp):\n241\t                    _reset_revised_flag(decomp)\n242\t        return \"REVISE_DECOMP\", \"REVIEW_DECOMP → REVISE_DECOMP: first revision (unconditional)\"\n243\t\n244\t    # --- REVISE_DECOMP → RE_REVIEW_CHECK ---\n245\t    if phase == \"REVISE_DECOMP\":\n246\t        if not dry_run:\n247\t            _compute_ai_scores(\"tmp/pipeline-active-ids.txt\")\n248\t        return \"RE_REVIEW_CHECK\", \"REVISE_DECOMP → RE_REVIEW_CHECK\"\n249\t\n250\t    # --- RE_REVIEW_CHECK: did revision change anything? ---\n251\t    if phase == \"RE_REVIEW_CHECK\":\n252\t        from artifact_utils import read_frontmatter\n253\t        cycle = state.get(\"revise_cycle\", 0)\n254\t        if cycle == 0:\n255\t            check_ids = _read_ids(\"tmp/pipeline-active-ids.txt\")\n256\t        else:\n257\t            check_ids = _read_ids(\"tmp/pipeline-revise-ids.txt\")\n258\t        revised_ids = []\n259\t        for strat_id in check_ids:\n260\t            decomp_path = f\"artifacts/epic-tasks/{strat_id}-decomposition.md\"\n261\t            if os.path.exists(decomp_path):\n262\t                try:\n263\t                    data, _ = read_frontmatter(decomp_path)\n264\t                    if data and data.get(\"revised\"):\n265\t                        revised_ids.append(strat_id)\n266\t                except Exception:\n267\t                    pass\n268\t        if not revised_ids:\n269\t            return \"BATCH_DONE\", \"RE_REVIEW_CHECK → BATCH_DONE: revision made no changes\"\n270\t        if not dry_run:\n271\t            _write_ids(\"tmp/pipeline-revise-ids.txt\", revised_ids)\n272\t            # Delete old review files so the poller can detect fresh reviews\n273\t            for strat_id in revised_ids:\n274\t                review_path = f\"artifacts/epic-reviews/{strat_id}-decomp-review.md\"\n275\t                if os.path.exists(review_path):\n276\t                    os.remove(review_path)\n277\t        return (\"RE_REVIEW\",\n278\t                f\"RE_REVIEW_CHECK → RE_REVIEW: {len(revised_ids)} revised\")\n279\t\n280\t    # --- RE_REVIEW → REVISE_CHECK ---\n281\t    if phase == \"RE_REVIEW\":\n282\t        return \"REVISE_CHECK\", \"RE_REVIEW → REVISE_CHECK\"\n283\t\n284\t    # --- REVISE_CHECK: only revise again if review fails, with cycle cap ---\n285\t    if phase == \"REVISE_CHECK\":\n286\t        from artifact_utils import read_frontmatter\n287\t        revise_ids = _read_ids(\"tmp/pipeline-revise-ids.txt\")\n288\t        failing_ids = []\n289\t        for strat_id in revise_ids:\n290\t            review_path = f\"artifacts/epic-reviews/{strat_id}-decomp-review.md\"\n291\t            if os.path.exists(review_path):\n292\t                try:\n293\t                    data, _ = read_frontmatter(review_path)\n294\t                    if data and not data.get(\"pass\", True):\n295\t                        failing_ids.append(strat_id)\n296\t                except Exception:\n297\t                    pass\n298\t        cycle = state.get(\"revise_cycle\", 0)\n299\t        if failing_ids and cycle < 2:\n300\t            if not dry_run:\n301\t                state[\"revise_cycle\"] = cycle + 1\n302\t                _write_ids(\"tmp/pipeline-revise-ids.txt\", failing_ids)\n303\t                # Reset revised flag so poller detects new changes\n304\t                for strat_id in failing_ids:\n305\t                    decomp_path = f\"artifacts/epic-tasks/{strat_id}-decomposition.md\"\n306\t                    if os.path.exists(decomp_path):\n307\t                        _reset_revised_flag(decomp_path)\n308\t            return (\"RE_REVISE\",\n309\t                    f\"REVISE_CHECK → RE_REVISE:\"\n310\t                    f\" failing={len(failing_ids)} cycle={cycle + 1}/2\")\n311\t        return \"BATCH_DONE\", \"REVISE_CHECK → BATCH_DONE: review passed or cycle cap reached\"\n312\t\n313\t    # --- RE_REVISE → RE_REVIEW_CHECK (loop back) ---\n314\t    if phase == \"RE_REVISE\":\n315\t        if not dry_run:\n316\t            _compute_ai_scores(\"tmp/pipeline-revise-ids.txt\")\n317\t        return \"RE_REVIEW_CHECK\", \"RE_REVISE → RE_REVIEW_CHECK\"\n318\t\n319\t    # --- BATCH_DONE decision ---\n320\t    if phase == \"BATCH_DONE\":\n321\t        batch = state.get(\"batch\", 0)\n322\t        total = state.get(\"total_batches\", 1)\n323\t        retry = state.get(\"retry_cycle\", 0)\n324\t        active_ids = _read_ids(\"tmp/pipeline-active-ids.txt\")\n325\t        batch_stats = f\"{len(active_ids)} strategies\"\n326\t        prefix = \"Retry batch\" if retry > 0 else \"Batch\"\n327\t        summary = f\"{prefix} {batch}/{total} complete: {batch_stats}\"\n328\t        if batch < total:\n329\t            return (\"BATCH_START\",\n330\t                    f\"{summary}\\nBATCH_DONE → BATCH_START\")\n331\t        if retry < 1:\n332\t            # Check for errors\n333\t            all_ids = _read_ids(\"tmp/pipeline-all-ids.txt\")\n334\t            error_ids = []\n335\t            for strat_id in all_ids:\n336\t                review_path = f\"artifacts/epic-reviews/{strat_id}-decomp-review.md\"\n337\t                if os.path.exists(review_path):\n338\t                    try:\n339\t                        from artifact_utils import read_frontmatter\n340\t                        data, _ = read_frontmatter(review_path)\n341\t                        if data and data.get(\"error\"):\n342\t                            error_ids.append(strat_id)\n343\t                    except Exception:\n344\t                        pass\n345\t                decomp_path = f\"artifacts/epic-tasks/{strat_id}-decomposition.md\"\n346\t                if not os.path.exists(decomp_path):\n347\t                    error_ids.append(strat_id)\n348\t            error_ids = list(dict.fromkeys(error_ids))\n349\t            if error_ids:\n350\t                return (\"ERROR_COLLECT\",\n351\t                        f\"{summary}\\nBATCH_DONE → ERROR_COLLECT:\"\n352\t                        f\" errors={len(error_ids)}\")\n353\t        return \"REPORT\", f\"{summary}\\nBATCH_DONE → REPORT\"\n354\t\n355\t    # --- ERROR_COLLECT → BATCH_START ---\n356\t    if phase == \"ERROR_COLLECT\":\n357\t        retry_ids = _read_ids(\"tmp/pipeline-retry-ids.txt\")\n358\t        n = len(retry_ids)\n359\t        batch = state.get(\"total_batches\", 0)\n360\t        return (\"BATCH_START\",\n361\t                f\"ERROR_COLLECT: retry batch {batch} with {n} error IDs\\n\"\n362\t                f\"ERROR_COLLECT → BATCH_START\")\n363\t\n364\t    # --- REPORT → DONE (with optional announce) ---\n365\t    if phase == \"REPORT\":\n366\t        if not dry_run and state.get(\"announce_complete\"):\n367\t            _run_script(\"python3 scripts/finish.py\")\n368\t        return \"DONE\", \"REPORT → DONE\"\n369\t\n370\t    print(f\"No transition defined for phase: {phase}\", file=sys.stderr)\n371\t    sys.exit(1)\n372\t\n373\t\n374\t# ---------- CLI commands ----------\n375\t\n376\t\n377\tdef cmd_init(args):\n378\t    parser = argparse.ArgumentParser(prog=\"pipeline_state.py init\")\n379\t    parser.add_argument(\"--batch-size\", type=int, default=25)\n380\t    parser.add_argument(\"--headless\", action=\"store_true\")\n381\t    parser.add_argument(\"--announce-complete\", action=\"store_true\")\n382\t    opts = parser.parse_args(args)\n383\t\n384\t    os.makedirs(\"tmp\", exist_ok=True)\n385\t    for f in glob.glob(\"tmp/pipeline-batch-*-ids.txt\"):\n386\t        os.remove(f)\n387\t    if os.path.exists(DISPATCH_MARKER):\n388\t        os.remove(DISPATCH_MARKER)\n389\t    state = {\n390\t        \"phase\": \"INIT\",\n391\t        \"batch\": 0,\n392\t        \"total_batches\": 0,\n393\t        \"headless\": opts.headless,\n394\t        \"announce_complete\": opts.announce_complete,\n395\t        \"batch_size\": opts.batch_size,\n396\t        \"start_time\": datetime.now(timezone.utc).strftime(\n397\t            \"%Y-%m-%dT%H:%M:%SZ\"),\n398\t        \"retry_cycle\": 0,\n399\t    }\n400\t    _save_state(state)\n401\t    print(f\"Initialized pipeline state: batch_size={opts.batch_size}\")\n402\t\n403\t\n404\tdef cmd_get_phase(args):\n405\t    state = _load_state()\n406\t    print(state[\"phase\"])\n407\t\n408\t\n409\tdef cmd_set_phase(args):\n410\t    if not args or args[0] not in PHASES:\n411\t        print(f\"Usage: set-phase <PHASE>\\nValid phases: {', '.join(PHASES)}\",\n412\t              file=sys.stderr)\n413\t        sys.exit(1)\n414\t    state = _load_state()\n415\t    state[\"phase\"] = args[0]\n416\t    _save_state(state)\n417\t    print(args[0])\n418\t\n419\t\n420\tdef cmd_get_phase_config(args):\n421\t    state = _load_state()\n422\t    phase = state[\"phase\"]\n423\t    config = dict(PHASE_CONFIG.get(phase, {\"type\": \"noop\"}))\n424\t    config[\"phase\"] = phase\n425\t    config.pop(\"command\", None)\n426\t    config.pop(\"pre_script\", None)\n427\t    config.pop(\"post_verify\", None)\n428\t    if config.get(\"type\") == \"script\":\n429\t        config.pop(\"ids_file\", None)\n430\t    if config.get(\"type\") == \"agent\":\n431\t        max_concurrent = int(state.get(\"batch_size\", 25))\n432\t        n_parallel = len(config.get(\"parallel\", []))\n433\t        config[\"wave_size\"] = max(1, max_concurrent // (1 + n_parallel))\n434\t    print(yaml.dump(config, default_flow_style=False, sort_keys=False),\n435\t          end=\"\")\n436\t\n437\t\n438\tdef cmd_run_phase(args):\n439\t    state = _load_state()\n440\t    phase = state[\"phase\"]\n441\t    config = PHASE_CONFIG.get(phase, {\"type\": \"noop\"})\n442\t    phase_type = config.get(\"type\", \"noop\")\n443\t    if phase_type != \"script\":\n444\t        print(f\"run-phase: phase {phase} is type '{phase_type}', not 'script'\",\n445\t              file=sys.stderr)\n446\t        sys.exit(1)\n447\t    cmd = config[\"command\"].format_map(state)\n448\t    if config.get(\"ids_file\"):\n449\t        ids = _read_ids(config[\"ids_file\"])\n450\t        if ids:\n451\t            cmd += \" \" + \" \".join(ids)\n452\t        else:\n453\t            print(f\"[run-phase] {phase}: no IDs, skipping\")\n454\t            with open(DISPATCH_MARKER, \"w\") as f:\n455\t                f.write(phase)\n456\t            return\n457\t    print(f\"[run-phase] {phase}\")\n458\t    result = subprocess.run(cmd, shell=True)\n459\t    if result.returncode != 0:\n460\t        sys.exit(result.returncode)\n461\t    with open(DISPATCH_MARKER, \"w\") as f:\n462\t        f.write(phase)\n463\t\n464\t\n465\tdef cmd_set_wave(args):\n466\t    if not args:\n467\t        print(\"Usage: set-wave ID1 ID2 ...\", file=sys.stderr)\n468\t        sys.exit(1)\n469\t    _write_ids(WAVE_IDS_FILE, args)\n470\t    print(f\"Wave: {len(args)} IDs\")\n471\t\n472\t\n473\tdef cmd_next_action(args):\n474\t    from check_decompose_progress import check_id\n475\t\n476\t    state = _load_state()\n477\t    phase = state[\"phase\"]\n478\t\n479\t    if phase == \"DONE\":\n480\t        print(yaml.dump({\"action\": \"done\", \"message\": \"Pipeline complete\"},\n481\t                        default_flow_style=False, sort_keys=False), end=\"\")\n482\t        return\n483\t\n484\t    if phase not in PHASES:\n485\t        print(f\"next-action: phase '{phase}' is not dispatchable.\"\n486\t              \" Run init and set-phase BATCH_START first.\",\n487\t              file=sys.stderr)\n488\t        sys.exit(1)\n489\t\n490\t    for _ in range(MAX_NEXT_ACTION_ITERATIONS):\n491\t        phase = state[\"phase\"]\n492\t        config = PHASE_CONFIG.get(phase, {\"type\": \"noop\"})\n493\t        phase_type = config.get(\"type\", \"noop\")\n494\t\n495\t        # --- DONE ---\n496\t        if phase == \"DONE\":\n497\t            print(yaml.dump(\n498\t                {\"action\": \"done\", \"message\": \"Pipeline complete\"},\n499\t                default_flow_style=False, sort_keys=False), end=\"\")\n500\t            return\n501\t\n502\t        # --- Noop: advance and loop ---\n503\t        if phase_type == \"noop\":\n504\t            next_phase, summary = advance(state)\n505\t            state[\"phase\"] = next_phase\n506\t            _save_state(state)\n507\t            print(summary, file=sys.stderr)\n508\t            continue\n509\t\n510\t        # --- Script: check dispatch marker ---\n511\t        if phase_type == \"script\":\n512\t            if os.path.exists(DISPATCH_MARKER):\n513\t                with open(DISPATCH_MARKER) as f:\n514\t                    marker_phase = f.read().strip()\n515\t                if marker_phase == phase:\n516\t                    os.remove(DISPATCH_MARKER)\n517\t                    next_phase, summary = advance(state)\n518\t                    state[\"phase\"] = next_phase\n519\t                    _save_state(state)\n520\t                    print(summary, file=sys.stderr)\n521\t                    continue\n522\t                else:\n523\t                    os.remove(DISPATCH_MARKER)\n524\t            print(yaml.dump(\n525\t                {\"action\": \"run_script\", \"phase\": phase,\n526\t                 \"message\": f\"{phase}: run-phase\"},\n527\t                default_flow_style=False, sort_keys=False), end=\"\")\n528\t            return\n529\t\n530\t        # --- Agent: compute next wave ---\n531\t        if phase_type == \"agent\":\n532\t            ids_file = config.get(\"ids_file\", \"\")\n533\t            all_ids = _read_ids(ids_file)\n534\t            poll_phase = config.get(\"poll_phase\", \"\")\n535\t\n536\t            phases_to_check = [poll_phase] if poll_phase else []\n537\t            for p in config.get(\"parallel\", []):\n538\t                if p.get(\"poll_phase\"):\n539\t                    phases_to_check.append(p[\"poll_phase\"])\n540\t\n541\t            remaining = []\n542\t            for strat_id in all_ids:\n543\t                for pphase in phases_to_check:\n544\t                    if check_id(pphase, strat_id) == \"pending\":\n545\t                        remaining.append(strat_id)\n546\t                        break\n547\t\n548\t            if not remaining:\n549\t                if config.get(\"post_verify\"):\n550\t                    _run_script(config[\"post_verify\"])\n551\t                next_phase, summary = advance(state)\n552\t                state[\"phase\"] = next_phase\n553\t                _save_state(state)\n554\t                print(summary, file=sys.stderr)\n555\t                continue\n556\t\n557\t            max_concurrent = int(state.get(\"batch_size\", 25))\n558\t            n_parallel = len(config.get(\"parallel\", []))\n559\t            wave_size = max(1, max_concurrent // (1 + n_parallel))\n560\t\n561\t            wave_ids = remaining[:wave_size]\n562\t            wave_num = 1 + (len(all_ids) - len(remaining)) // wave_size\n563\t            total_waves = max(1, -(-len(all_ids) // wave_size))\n564\t\n565\t            if config.get(\"pre_script\"):\n566\t                for strat_id in wave_ids:\n567\t                    cmd = config[\"pre_script\"].replace(\"{ID}\", strat_id)\n568\t                    _run_script(cmd)\n569\t\n570\t            _write_ids(WAVE_IDS_FILE, wave_ids)\n571\t\n572\t            agents = []\n573\t            for strat_id in wave_ids:\n574\t                entry = {}\n575\t                if config.get(\"subagent_type\"):\n576\t                    entry[\"subagent_type\"] = config[\"subagent_type\"]\n577\t                entry[\"prompt_file\"] = config[\"prompt\"]\n578\t                var_lines = []\n579\t                for k, v in config.get(\"vars\", {}).items():\n580\t                    var_lines.append(\n581\t                        f\"{k}={v.replace('{ID}', strat_id)}\")\n582\t                entry[\"vars\"] = \"\\n\".join(var_lines) + \"\\n\"\n583\t                agents.append(entry)\n584\t\n585\t                for par in config.get(\"parallel\", []):\n586\t                    pentry = {}\n587\t                    if par.get(\"subagent_type\"):\n588\t                        pentry[\"subagent_type\"] = par[\"subagent_type\"]\n589\t                    pentry[\"prompt_file\"] = par[\"prompt\"]\n590\t                    pvar_lines = []\n591\t                    for k, v in par.get(\"vars\", {}).items():\n592\t                        pvar_lines.append(\n593\t                            f\"{k}={v.replace('{ID}', strat_id)}\")\n594\t                    pentry[\"vars\"] = \"\\n\".join(pvar_lines) + \"\\n\"\n595\t                    agents.append(pentry)\n596\t\n597\t            msg = (f\"{phase}: wave {wave_num}/{total_waves}\"\n598\t                   f\" ({len(wave_ids)} IDs)\")\n599\t            output = {\n600\t                \"action\": \"launch_wave\",\n601\t                \"phase\": phase,\n602\t                \"message\": msg,\n603\t                \"agents\": agents,\n604\t            }\n605\t            print(yaml.dump(output, Dumper=_BlockDumper,\n606\t                            default_flow_style=False, sort_keys=False),\n607\t                  end=\"\")\n608\t            return\n609\t\n610\t    print(f\"next-action: exceeded {MAX_NEXT_ACTION_ITERATIONS} iterations\"\n611\t          f\" at phase {state['phase']}\", file=sys.stderr)\n612\t    sys.exit(1)\n613\t\n614\t\n615\tdef cmd_wait_for_wave(args):\n616\t    if not os.path.exists(WAVE_IDS_FILE):\n617\t        print(\"wait-for-wave: no wave file found\"\n618\t              f\" ({WAVE_IDS_FILE}). Run next-action first.\",\n619\t              file=sys.stderr)\n620\t        sys.exit(1)\n621\t\n622\t    wave_ids = _read_ids(WAVE_IDS_FILE)\n623\t    if not wave_ids:\n624\t        print(\"wait-for-wave: wave file is empty.\"\n625\t              \" All agents may already be complete.\",\n626\t              file=sys.stderr)\n627\t        return\n628\t\n629\t    state = _load_state()\n630\t    phase = state[\"phase\"]\n631\t    config = PHASE_CONFIG.get(phase, {\"type\": \"noop\"})\n632\t\n633\t    poll_phase = config.get(\"poll_phase\")\n634\t    if not poll_phase:\n635\t        print(f\"wait-for-wave: phase {phase} has no poll_phase\",\n636\t              file=sys.stderr)\n637\t        sys.exit(1)\n638\t\n639\t    cmd_parts = [\n640\t        sys.executable,\n641\t        os.path.join(os.path.dirname(__file__),\n642\t                     \"check_decompose_progress.py\"),\n643\t        \"--wait\",\n644\t        \"--max-wait\", \"90\",\n645\t        \"--phase\", poll_phase,\n646\t    ]\n647\t    for p in config.get(\"parallel\", []):\n648\t        if p.get(\"poll_phase\"):\n649\t            cmd_parts.extend([\"--also-phase\", p[\"poll_phase\"]])\n650\t    if not state.get(\"headless\", True):\n651\t        cmd_parts.append(\"--fast-poll\")\n652\t    cmd_parts.extend([\"--id-file\", WAVE_IDS_FILE])\n653\t\n654\t    result = subprocess.run(cmd_parts)\n655\t    if result.returncode == 0:\n656\t        return\n657\t    if result.returncode == 3:\n658\t        print(\"Re-run: python3 scripts/pipeline_state.py wait-for-wave\")\n659\t        sys.exit(3)\n660\t    print(f\"wait-for-wave: check_decompose_progress.py exited with\"\n661\t          f\" code {result.returncode}\", file=sys.stderr)\n662\t    sys.exit(result.returncode)\n663\t\n664\t\n665\tdef _check_agent_phase_complete(config):\n666\t    ids_file = config.get(\"ids_file\")\n667\t    poll_phase = config.get(\"poll_phase\")\n668\t    if not ids_file or not poll_phase:\n669\t        return True\n670\t    ids = _read_ids(ids_file)\n671\t    if not ids:\n672\t        return True\n673\t    from check_decompose_progress import check_id\n674\t    phases_to_check = [poll_phase]\n675\t    for p in config.get(\"parallel\", []):\n676\t        if p.get(\"poll_phase\"):\n677\t            phases_to_check.append(p[\"poll_phase\"])\n678\t    for phase in phases_to_check:\n679\t        for strat_id in ids:\n680\t            if check_id(phase, strat_id) == \"pending\":\n681\t                return False\n682\t    return True\n683\t\n684\t\n685\tdef cmd_advance(args):\n686\t    dry_run = \"--dry-run\" in args\n687\t    state = _load_state()\n688\t    phase = state[\"phase\"]\n689\t    config = PHASE_CONFIG.get(phase, {\"type\": \"noop\"})\n690\t    phase_type = config.get(\"type\", \"noop\")\n691\t    if phase_type == \"script\" and not dry_run:\n692\t        if not os.path.exists(DISPATCH_MARKER):\n693\t            print(f\"advance: script phase {phase} was not dispatched.\"\n694\t                  \" Run: python3 scripts/pipeline_state.py next-action\",\n695\t                  file=sys.stderr)\n696\t            sys.exit(1)\n697\t        with open(DISPATCH_MARKER) as f:\n698\t            marker_phase = f.read().strip()\n699\t        os.remove(DISPATCH_MARKER)\n700\t        if marker_phase != phase:\n701\t            print(f\"advance: dispatch marker is for {marker_phase},\"\n702\t                  f\" not current phase {phase}\", file=sys.stderr)\n703\t            sys.exit(1)\n704\t    if phase_type == \"agent\" and not dry_run:\n705\t        if not _check_agent_phase_complete(config):\n706\t            print(f\"advance: agent phase {phase} has pending agents.\"\n707\t                  f\" Run: python3 scripts/pipeline_state.py\"\n708\t                  f\" wait-for-wave\",\n709\t                  file=sys.stderr)\n710\t            sys.exit(1)\n711\t    next_phase, summary = advance(state, dry_run=dry_run)\n712\t    if not dry_run:\n713\t        state[\"phase\"] = next_phase\n714\t        _save_state(state)\n715\t    print(summary)\n716\t\n717\t\n718\tdef cmd_set(args):\n719\t    if not args:\n720\t        print(\"Usage: set key=value ...\", file=sys.stderr)\n721\t        sys.exit(1)\n722\t    state = _load_state()\n723\t    for arg in args:\n724\t        if \"=\" not in arg:\n725\t            print(f\"Invalid key=value: {arg}\", file=sys.stderr)\n726\t            sys.exit(1)\n727\t        k, v = arg.split(\"=\", 1)\n728\t        if v.isdigit():\n729\t            v = int(v)\n730\t        elif v.lower() in (\"true\", \"false\"):\n731\t            v = v.lower() == \"true\"\n732\t        state[k] = v\n733\t    _save_state(state)\n734\t\n735\t\n736\tdef cmd_get(args):\n737\t    if not args:\n738\t        print(\"Usage: get <key>\", file=sys.stderr)\n739\t        sys.exit(1)\n740\t    state = _load_state()\n741\t    val = state.get(args[0])\n742\t    if val is None:\n743\t        sys.exit(1)\n744\t    print(val)\n745\t\n746\t\n747\tdef cmd_status(args):\n748\t    state = _load_state()\n749\t    print(yaml.dump(state, default_flow_style=False, sort_keys=False),\n750\t          end=\"\")\n751\t\n752\t\n753\tdef cmd_diagnose(args):\n754\t    state = _load_state()\n755\t    phase = state[\"phase\"]\n756\t    print(f\"Phase: {phase}\")\n757\t    print(f\"Batch: {state.get('batch', 0)}/{state.get('total_batches', 0)}\")\n758\t    print(f\"Revise cycle: {state.get('revise_cycle', 0)}/2\")\n759\t    print(f\"Retry cycle: {state.get('retry_cycle', 0)}/1\")\n760\t\n761\t    id_files = [\n762\t        \"tmp/pipeline-all-ids.txt\",\n763\t        \"tmp/pipeline-active-ids.txt\",\n764\t        \"tmp/pipeline-revise-ids.txt\",\n765\t        \"tmp/pipeline-retry-ids.txt\",\n766\t    ]\n767\t    print(\"\\nID files:\")\n768\t    for f in id_files:\n769\t        if os.path.exists(f):\n770\t            ids = _read_ids(f)\n771\t            print(f\"  {f}: {len(ids)} IDs\")\n772\t        else:\n773\t            print(f\"  {f}: (missing)\")\n774\t\n775\t    active = _read_ids(\"tmp/pipeline-active-ids.txt\")\n776\t    if active:\n777\t        missing_strat = []\n778\t        missing_decomp = []\n779\t        error_ids = []\n780\t        for strat_id in active:\n781\t            if not os.path.exists(f\"artifacts/strat-tasks/{strat_id}.md\"):\n782\t                missing_strat.append(strat_id)\n783\t            decomp = f\"artifacts/epic-tasks/{strat_id}-decomposition.md\"\n784\t            if not os.path.exists(decomp):\n785\t                missing_decomp.append(strat_id)\n786\t            review = f\"artifacts/epic-reviews/{strat_id}-decomp-review.md\"\n787\t            if os.path.exists(review):\n788\t                try:\n789\t                    from artifact_utils import read_frontmatter\n790\t                    data, _ = read_frontmatter(review)\n791\t                    if data and data.get(\"error\"):\n792\t                        error_ids.append(strat_id)\n793\t                except Exception:\n794\t                    pass\n795\t        print(f\"\\nActive IDs: {len(active)}\")\n796\t        if missing_strat:\n797\t            print(f\"  Missing strategy files: {', '.join(missing_strat)}\")\n798\t        if missing_decomp:\n799\t            print(f\"  Missing decomposition files: {', '.join(missing_decomp)}\")\n800\t        if error_ids:\n801\t            print(f\"  Error IDs: {', '.join(error_ids)}\")\n802\t\n803\t\n804\tDISPATCH_LOOP = \"\"\"\\\n805\tResume the dispatch loop:\n806\t  1. python3 scripts/pipeline_state.py next-action\n807\t  2. If action == done: exit loop, run teardown\n808\t  3. If action == run_script: python3 scripts/pipeline_state.py run-phase, then go to 1\n809\t  4. If action == launch_wave:\n810\t     a. For each agent in agents: launch background Agent(prompt=vars + \"\\\\n\\\\nRead \" + prompt_file + \" and follow all instructions exactly.\", subagent_type if present)\n811\t     b. python3 scripts/pipeline_state.py wait-for-wave (re-run on exit 3), then go to 1\"\"\"\n812\t\n813\t\n814\tdef cmd_dispatch_context(args):\n815\t    if not os.path.exists(STATE_FILE):\n816\t        return\n817\t    state = _load_state()\n818\t    phase = state[\"phase\"]\n819\t    if phase not in PHASES:\n820\t        print(f\"[PIPELINE STATE RECOVERY] Setup in progress (phase: {phase})\")\n821\t        print(\"Setup is not yet complete. Re-read SKILL.md\"\n822\t              \" (skills/epic-decompose/SKILL.md) and resume\"\n823\t              \" the setup steps from where you left off.\")\n824\t        return\n825\t    if phase == \"DONE\":\n826\t        print(\"[PIPELINE STATE RECOVERY] Pipeline complete (phase: DONE)\")\n827\t        return\n828\t    config = PHASE_CONFIG.get(phase, {\"type\": \"noop\"})\n829\t    phase_type = config.get(\"type\", \"noop\")\n830\t    print(f\"[PIPELINE STATE RECOVERY] Current phase: {phase}\"\n831\t          f\" (type: {phase_type})\")\n832\t    print(f\"Batch: {state.get('batch', 0)}/{state.get('total_batches', 0)}\")\n833\t    print()\n834\t    print(DISPATCH_LOOP)\n835\t\n836\t\n837\tdef cmd_post_compact_hook(args):\n838\t    if not os.environ.get(\"EPIC_CREATOR_ENABLE_CONTEXT_HOOK\"):\n839\t        return\n840\t    cmd_dispatch_context(args)\n841\t\n842\t\n843\tCOMMANDS = {\n844\t    \"init\": cmd_init,\n845\t    \"get-phase\": cmd_get_phase,\n846\t    \"set-phase\": cmd_set_phase,\n847\t    \"get-phase-config\": cmd_get_phase_config,\n848\t    \"run-phase\": cmd_run_phase,\n849\t    \"set-wave\": cmd_set_wave,\n850\t    \"next-action\": cmd_next_action,\n851\t    \"wait-for-wave\": cmd_wait_for_wave,\n852\t    \"advance\": cmd_advance,\n853\t    \"set\": cmd_set,\n854\t    \"get\": cmd_get,\n855\t    \"status\": cmd_status,\n856\t    \"diagnose\": cmd_diagnose,\n857\t    \"dispatch-context\": cmd_dispatch_context,\n858\t    \"post-compact-hook\": cmd_post_compact_hook,\n859\t}\n860\t\n861\tif __name__ == \"__main__\":\n862\t    if len(sys.argv) < 2 or sys.argv[1] not in COMMANDS:\n863\t        print(f\"Commands: {', '.join(COMMANDS)}\", file=sys.stderr)\n864\t        sys.exit(1)\n865\t    COMMANDS[sys.argv[1]](sys.argv[2:])\n866\t"}]},"parent_tool_use_id":null,"session_id":"ffc190d1-a457-4608-ad90-0fad47057ac1","uuid":"f5736663-86c3-4bc4-9ea8-0cc70b0db982","timestamp":"2026-10-09T13:58:54.004Z","tool_use_result":{"type":"text","file":{"filePath":"/private/var/folders/h5/l8qslbp55w5621qf9ngsh5jc0000gn/T/epic_case-021-real-pqc-base-image-compliance_0_yhs98llf/scripts/pipeline_state.py","content":"#!/usr/bin/env python3\n\"\"\"Pipeline state machine for the thin dispatcher.\n\nPhase tracking, config, and transition logic for epic-decompose.\n\nUsage:\n    python3 scripts/pipeline_state.py init [--batch-size N] [--headless]\n    python3 scripts/pipeline_state.py get-phase\n    python3 scripts/pipeline_state.py set-phase <PHASE>\n    python3 scripts/pipeline_state.py get-phase-config\n    python3 scripts/pipeline_state.py run-phase\n    python3 scripts/pipeline_state.py advance [--dry-run]\n    python3 scripts/pipeline_state.py set-wave <IDs>\n    python3 scripts/pipeline_state.py set key=value ...\n    python3 scripts/pipeline_state.py get <key>\n    python3 scripts/pipeline_state.py status\n    python3 scripts/pipeline_state.py diagnose\n\"\"\"\n\nimport argparse\nimport glob\nimport os\nimport shutil\nimport subprocess\nimport sys\nfrom datetime import datetime, timezone\n\nimport yaml\n\nSTATE_FILE = \"tmp/pipeline-state.yaml\"\nWAVE_IDS_FILE = \"tmp/pipeline-wave-ids.txt\"\nDISPATCH_MARKER = \"tmp/.dispatch-marker\"\n\nMAX_NEXT_ACTION_ITERATIONS = 50\n\n\n# ---------- YAML block-scalar dumper (scoped) ----------\n\ndef _str_representer(dumper, data):\n    if '\\n' in data:\n        return dumper.represent_scalar(\n            'tag:yaml.org,2002:str', data, style='|')\n    return dumper.represent_scalar('tag:yaml.org,2002:str', data)\n\n\nclass _BlockDumper(yaml.Dumper):\n    pass\n\n\n_BlockDumper.add_representer(str, _str_representer)\n\n# ---------- Phase enum ----------\n\nPHASES = [\n    \"BATCH_START\", \"FETCH\", \"DECOMPOSE\", \"REVIEW_DECOMP\",\n    \"REVISE_DECOMP\",\n    \"RE_REVIEW_CHECK\", \"RE_REVIEW\", \"REVISE_CHECK\", \"RE_REVISE\",\n    \"BATCH_DONE\", \"ERROR_COLLECT\",\n    \"REPORT\", \"DONE\",\n]\n\n# ---------- Phase config ----------\n\nPHASE_CONFIG = {\n    \"BATCH_START\": {\"type\": \"noop\"},\n    \"FETCH\": {\n        \"type\": \"agent\",\n        \"prompt\": \"skills/epic-decompose/prompts/fetch-agent.md\",\n        \"ids_file\": \"tmp/pipeline-active-ids.txt\",\n        \"poll_phase\": \"fetch\",\n        \"vars\": {\"ID\": \"{ID}\"},\n    },\n    \"DECOMPOSE\": {\n        \"type\": \"agent\",\n        \"prompt\": \"skills/epic-decompose/prompts/decompose-agent.md\",\n        \"ids_file\": \"tmp/pipeline-active-ids.txt\",\n        \"poll_phase\": \"decompose\",\n        \"vars\": {\"ID\": \"{ID}\"},\n    },\n    \"REVIEW_DECOMP\": {\n        \"type\": \"agent\",\n        \"prompt\": \"skills/epic-decompose/prompts/review-agent.md\",\n        \"ids_file\": \"tmp/pipeline-active-ids.txt\",\n        \"poll_phase\": \"review_decomp\",\n        \"vars\": {\"ID\": \"{ID}\"},\n    },\n    \"REVISE_DECOMP\": {\n        \"type\": \"agent\",\n        \"prompt\": \"skills/epic-decompose/prompts/revise-agent.md\",\n        \"ids_file\": \"tmp/pipeline-active-ids.txt\",\n        \"poll_phase\": \"revise_decomp\",\n        \"vars\": {\"ID\": \"{ID}\"},\n    },\n    \"RE_REVIEW_CHECK\": {\"type\": \"noop\"},\n    \"RE_REVIEW\": {\n        \"type\": \"agent\",\n        \"prompt\": \"skills/epic-decompose/prompts/review-agent.md\",\n        \"ids_file\": \"tmp/pipeline-revise-ids.txt\",\n        \"poll_phase\": \"review_decomp\",\n        \"vars\": {\"ID\": \"{ID}\"},\n    },\n    \"REVISE_CHECK\": {\"type\": \"noop\"},\n    \"RE_REVISE\": {\n        \"type\": \"agent\",\n        \"prompt\": \"skills/epic-decompose/prompts/revise-agent.md\",\n        \"ids_file\": \"tmp/pipeline-revise-ids.txt\",\n        \"poll_phase\": \"revise_decomp\",\n        \"vars\": {\"ID\": \"{ID}\"},\n    },\n\n    # --- Batch control + retry ---\n    \"BATCH_DONE\": {\"type\": \"noop\"},\n    \"ERROR_COLLECT\": {\n        \"type\": \"script\",\n        \"command\": \"python3 scripts/error_collect.py\",\n    },\n\n    # --- Terminal ---\n    \"REPORT\": {\n        \"type\": \"script\",\n        \"command\": (\"python3 scripts/generate_run_report.py\"\n                    \" --start-time {start_time}\"\n                    \" --batch-size {batch_size}\"),\n    },\n}\n\n# ---------- State helpers ----------\n\n\ndef _load_state():\n    if not os.path.exists(STATE_FILE):\n        print(f\"State file not found: {STATE_FILE}\", file=sys.stderr)\n        sys.exit(1)\n    with open(STATE_FILE) as f:\n        return yaml.safe_load(f)\n\n\ndef _save_state(state):\n    os.makedirs(os.path.dirname(STATE_FILE), exist_ok=True)\n    with open(STATE_FILE, \"w\") as f:\n        yaml.dump(state, f, default_flow_style=False, sort_keys=False)\n\n\ndef _read_ids(path):\n    if not os.path.exists(path):\n        return []\n    with open(path) as f:\n        return [line.strip() for line in f if line.strip()]\n\n\ndef _write_ids(path, ids):\n    os.makedirs(os.path.dirname(path) or \"tmp\", exist_ok=True)\n    with open(path, \"w\") as f:\n        for id_ in ids:\n            f.write(f\"{id_}\\n\")\n\n\ndef _copy_ids(src, dst):\n    os.makedirs(os.path.dirname(dst) or \"tmp\", exist_ok=True)\n    shutil.copy2(src, dst)\n\n\ndef _reset_revised_flag(decomp_path):\n    \"\"\"Remove ``revised`` key from decomposition frontmatter.\n\n    The revise_decomp completion poller treats *any* non-None value\n    (including False) as \"completed\".  Removing the key forces it back to\n    \"pending\" so the revise agent is actually launched.\n    \"\"\"\n    from artifact_utils import read_frontmatter\n    data, body = read_frontmatter(decomp_path)\n    if data and \"revised\" in data:\n        del data[\"revised\"]\n        with open(decomp_path, \"w\") as f:\n            f.write(\"---\\n\")\n            f.write(yaml.dump(data, default_flow_style=False, sort_keys=False))\n            f.write(\"---\\n\")\n            f.write(body)\n\n\ndef _run_script(cmd):\n    result = subprocess.run(\n        cmd, shell=True, capture_output=True, text=True)\n    if result.returncode != 0:\n        print(\"Script failed (exit code \"\n              f\"{result.returncode})\", file=sys.stderr)\n        if result.stderr:\n            print(result.stderr, file=sys.stderr)\n        sys.exit(1)\n    return result.stdout.strip()\n\n\ndef _compute_ai_scores(ids_file):\n    \"\"\"Compute AI implementability scores from signal values in epic frontmatter.\"\"\"\n    ids = _read_ids(ids_file)\n    if not ids:\n        return\n    cmd = f\"python3 scripts/compute_ai_scores.py {' '.join(ids)}\"\n    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)\n    if result.stderr:\n        print(result.stderr, file=sys.stderr)\n\n\n# ---------- Transition logic ----------\n\nMAIN_SEQUENCE = [\"FETCH\", \"DECOMPOSE\", \"REVIEW_DECOMP\"]\n\n\ndef advance(state, dry_run=False):\n    \"\"\"Compute and apply the next phase transition.\n\n    Returns (next_phase, summary_line).\n    \"\"\"\n    phase = state[\"phase\"]\n\n    # --- BATCH_START: reset counters, populate active IDs ---\n    if phase == \"BATCH_START\":\n        batch = state.get(\"batch\", 0) + 1\n        if not dry_run:\n            state[\"batch\"] = batch\n            batch_file = f\"tmp/pipeline-batch-{batch}-ids.txt\"\n            _copy_ids(batch_file, \"tmp/pipeline-active-ids.txt\")\n        return \"FETCH\", f\"BATCH_START → FETCH: batch={batch}\"\n\n    # --- Linear main sequence ---\n    if phase in MAIN_SEQUENCE[:-1]:\n        nxt = MAIN_SEQUENCE[MAIN_SEQUENCE.index(phase) + 1]\n        if phase == \"DECOMPOSE\" and not dry_run:\n            _compute_ai_scores(\"tmp/pipeline-active-ids.txt\")\n        return nxt, f\"{phase} → {nxt}\"\n\n    # --- REVIEW_DECOMP → REVISE_DECOMP (unconditional first revision) ---\n    if phase == \"REVIEW_DECOMP\":\n        if not dry_run:\n            # Clear the ``revised`` default so the poller sees IDs as pending.\n            # The schema sets revised: false on creation, but the poller\n            # treats any non-None value as \"completed\".\n            for strat_id in _read_ids(\"tmp/pipeline-active-ids.txt\"):\n                decomp = f\"artifacts/epic-tasks/{strat_id}-decomposition.md\"\n                if os.path.exists(decomp):\n                    _reset_revised_flag(decomp)\n        return \"REVISE_DECOMP\", \"REVIEW_DECOMP → REVISE_DECOMP: first revision (unconditional)\"\n\n    # --- REVISE_DECOMP → RE_REVIEW_CHECK ---\n    if phase == \"REVISE_DECOMP\":\n        if not dry_run:\n            _compute_ai_scores(\"tmp/pipeline-active-ids.txt\")\n        return \"RE_REVIEW_CHECK\", \"REVISE_DECOMP → RE_REVIEW_CHECK\"\n\n    # --- RE_REVIEW_CHECK: did revision change anything? ---\n    if phase == \"RE_REVIEW_CHECK\":\n        from artifact_utils import read_frontmatter\n        cycle = state.get(\"revise_cycle\", 0)\n        if cycle == 0:\n            check_ids = _read_ids(\"tmp/pipeline-active-ids.txt\")\n        else:\n            check_ids = _read_ids(\"tmp/pipeline-revise-ids.txt\")\n        revised_ids = []\n        for strat_id in check_ids:\n            decomp_path = f\"artifacts/epic-tasks/{strat_id}-decomposition.md\"\n            if os.path.exists(decomp_path):\n                try:\n                    data, _ = read_frontmatter(decomp_path)\n                    if data and data.get(\"revised\"):\n                        revised_ids.append(strat_id)\n                except Exception:\n                    pass\n        if not revised_ids:\n            return \"BATCH_DONE\", \"RE_REVIEW_CHECK → BATCH_DONE: revision made no changes\"\n        if not dry_run:\n            _write_ids(\"tmp/pipeline-revise-ids.txt\", revised_ids)\n            # Delete old review files so the poller can detect fresh reviews\n            for strat_id in revised_ids:\n                review_path = f\"artifacts/epic-reviews/{strat_id}-decomp-review.md\"\n                if os.path.exists(review_path):\n                    os.remove(review_path)\n        return (\"RE_REVIEW\",\n                f\"RE_REVIEW_CHECK → RE_REVIEW: {len(revised_ids)} revised\")\n\n    # --- RE_REVIEW → REVISE_CHECK ---\n    if phase == \"RE_REVIEW\":\n        return \"REVISE_CHECK\", \"RE_REVIEW → REVISE_CHECK\"\n\n    # --- REVISE_CHECK: only revise again if review fails, with cycle cap ---\n    if phase == \"REVISE_CHECK\":\n        from artifact_utils import read_frontmatter\n        revise_ids = _read_ids(\"tmp/pipeline-revise-ids.txt\")\n        failing_ids = []\n        for strat_id in revise_ids:\n            review_path = f\"artifacts/epic-reviews/{strat_id}-decomp-review.md\"\n            if os.path.exists(review_path):\n                try:\n                    data, _ = read_frontmatter(review_path)\n                    if data and not data.get(\"pass\", True):\n                        failing_ids.append(strat_id)\n                except Exception:\n                    pass\n        cycle = state.get(\"revise_cycle\", 0)\n        if failing_ids and cycle < 2:\n            if not dry_run:\n                state[\"revise_cycle\"] = cycle + 1\n                _write_ids(\"tmp/pipeline-revise-ids.txt\", failing_ids)\n                # Reset revised flag so poller detects new changes\n                for strat_id in failing_ids:\n                    decomp_path = f\"artifacts/epic-tasks/{strat_id}-decomposition.md\"\n                    if os.path.exists(decomp_path):\n                        _reset_revised_flag(decomp_path)\n            return (\"RE_REVISE\",\n                    f\"REVISE_CHECK → RE_REVISE:\"\n                    f\" failing={len(failing_ids)} cycle={cycle + 1}/2\")\n        return \"BATCH_DONE\", \"REVISE_CHECK → BATCH_DONE: review passed or cycle cap reached\"\n\n    # --- RE_REVISE → RE_REVIEW_CHECK (loop back) ---\n    if phase == \"RE_REVISE\":\n        if not dry_run:\n            _compute_ai_scores(\"tmp/pipeline-revise-ids.txt\")\n        return \"RE_REVIEW_CHECK\", \"RE_REVISE → RE_REVIEW_CHECK\"\n\n    # --- BATCH_DONE decision ---\n    if phase == \"BATCH_DONE\":\n        batch = state.get(\"batch\", 0)\n        total = state.get(\"total_batches\", 1)\n        retry = state.get(\"retry_cycle\", 0)\n        active_ids = _read_ids(\"tmp/pipeline-active-ids.txt\")\n        batch_stats = f\"{len(active_ids)} strategies\"\n        prefix = \"Retry batch\" if retry > 0 else \"Batch\"\n        summary = f\"{prefix} {batch}/{total} complete: {batch_stats}\"\n        if batch < total:\n            return (\"BATCH_START\",\n                    f\"{summary}\\nBATCH_DONE → BATCH_START\")\n        if retry < 1:\n            # Check for errors\n            all_ids = _read_ids(\"tmp/pipeline-all-ids.txt\")\n            error_ids = []\n            for strat_id in all_ids:\n                review_path = f\"artifacts/epic-reviews/{strat_id}-decomp-review.md\"\n                if os.path.exists(review_path):\n                    try:\n                        from artifact_utils import read_frontmatter\n                        data, _ = read_frontmatter(review_path)\n                        if data and data.get(\"error\"):\n                            error_ids.append(strat_id)\n                    except Exception:\n                        pass\n                decomp_path = f\"artifacts/epic-tasks/{strat_id}-decomposition.md\"\n                if not os.path.exists(decomp_path):\n                    error_ids.append(strat_id)\n            error_ids = list(dict.fromkeys(error_ids))\n            if error_ids:\n                return (\"ERROR_COLLECT\",\n                        f\"{summary}\\nBATCH_DONE → ERROR_COLLECT:\"\n                        f\" errors={len(error_ids)}\")\n        return \"REPORT\", f\"{summary}\\nBATCH_DONE → REPORT\"\n\n    # --- ERROR_COLLECT → BATCH_START ---\n    if phase == \"ERROR_COLLECT\":\n        retry_ids = _read_ids(\"tmp/pipeline-retry-ids.txt\")\n        n = len(retry_ids)\n        batch = state.get(\"total_batches\", 0)\n        return (\"BATCH_START\",\n                f\"ERROR_COLLECT: retry batch {batch} with {n} error IDs\\n\"\n                f\"ERROR_COLLECT → BATCH_START\")\n\n    # --- REPORT → DONE (with optional announce) ---\n    if phase == \"REPORT\":\n        if not dry_run and state.get(\"announce_complete\"):\n            _run_script(\"python3 scripts/finish.py\")\n        return \"DONE\", \"REPORT → DONE\"\n\n    print(f\"No transition defined for phase: {phase}\", file=sys.stderr)\n    sys.exit(1)\n\n\n# ---------- CLI commands ----------\n\n\ndef cmd_init(args):\n    parser = argparse.ArgumentParser(prog=\"pipeline_state.py init\")\n    parser.add_argument(\"--batch-size\", type=int, default=25)\n    parser.add_argument(\"--headless\", action=\"store_true\")\n    parser.add_argument(\"--announce-complete\", action=\"store_true\")\n    opts = parser.parse_args(args)\n\n    os.makedirs(\"tmp\", exist_ok=True)\n    for f in glob.glob(\"tmp/pipeline-batch-*-ids.txt\"):\n        os.remove(f)\n    if os.path.exists(DISPATCH_MARKER):\n        os.remove(DISPATCH_MARKER)\n    state = {\n        \"phase\": \"INIT\",\n        \"batch\": 0,\n        \"total_batches\": 0,\n        \"headless\": opts.headless,\n        \"announce_complete\": opts.announce_complete,\n        \"batch_size\": opts.batch_size,\n        \"start_time\": datetime.now(timezone.utc).strftime(\n            \"%Y-%m-%dT%H:%M:%SZ\"),\n        \"retry_cycle\": 0,\n    }\n    _save_state(state)\n    print(f\"Initialized pipeline state: batch_size={opts.batch_size}\")\n\n\ndef cmd_get_phase(args):\n    state = _load_state()\n    print(state[\"phase\"])\n\n\ndef cmd_set_phase(args):\n    if not args or args[0] not in PHASES:\n        print(f\"Usage: set-phase <PHASE>\\nValid phases: {', '.join(PHASES)}\",\n              file=sys.stderr)\n        sys.exit(1)\n    state = _load_state()\n    state[\"phase\"] = args[0]\n    _save_state(state)\n    print(args[0])\n\n\ndef cmd_get_phase_config(args):\n    state = _load_state()\n    phase = state[\"phase\"]\n    config = dict(PHASE_CONFIG.get(phase, {\"type\": \"noop\"}))\n    config[\"phase\"] = phase\n    config.pop(\"command\", None)\n    config.pop(\"pre_script\", None)\n    config.pop(\"post_verify\", None)\n    if config.get(\"type\") == \"script\":\n        config.pop(\"ids_file\", None)\n    if config.get(\"type\") == \"agent\":\n        max_concurrent = int(state.get(\"batch_size\", 25))\n        n_parallel = len(config.get(\"parallel\", []))\n        config[\"wave_size\"] = max(1, max_concurrent // (1 + n_parallel))\n    print(yaml.dump(config, default_flow_style=False, sort_keys=False),\n          end=\"\")\n\n\ndef cmd_run_phase(args):\n    state = _load_state()\n    phase = state[\"phase\"]\n    config = PHASE_CONFIG.get(phase, {\"type\": \"noop\"})\n    phase_type = config.get(\"type\", \"noop\")\n    if phase_type != \"script\":\n        print(f\"run-phase: phase {phase} is type '{phase_type}', not 'script'\",\n              file=sys.stderr)\n        sys.exit(1)\n    cmd = config[\"command\"].format_map(state)\n    if config.get(\"ids_file\"):\n        ids = _read_ids(config[\"ids_file\"])\n        if ids:\n            cmd += \" \" + \" \".join(ids)\n        else:\n            print(f\"[run-phase] {phase}: no IDs, skipping\")\n            with open(DISPATCH_MARKER, \"w\") as f:\n                f.write(phase)\n            return\n    print(f\"[run-phase] {phase}\")\n    result = subprocess.run(cmd, shell=True)\n    if result.returncode != 0:\n        sys.exit(result.returncode)\n    with open(DISPATCH_MARKER, \"w\") as f:\n        f.write(phase)\n\n\ndef cmd_set_wave(args):\n    if not args:\n        print(\"Usage: set-wave ID1 ID2 ...\", file=sys.stderr)\n        sys.exit(1)\n    _write_ids(WAVE_IDS_FILE, args)\n    print(f\"Wave: {len(args)} IDs\")\n\n\ndef cmd_next_action(args):\n    from check_decompose_progress import check_id\n\n    state = _load_state()\n    phase = state[\"phase\"]\n\n    if phase == \"DONE\":\n        print(yaml.dump({\"action\": \"done\", \"message\": \"Pipeline complete\"},\n                        default_flow_style=False, sort_keys=False), end=\"\")\n        return\n\n    if phase not in PHASES:\n        print(f\"next-action: phase '{phase}' is not dispatchable.\"\n              \" Run init and set-phase BATCH_START first.\",\n              file=sys.stderr)\n        sys.exit(1)\n\n    for _ in range(MAX_NEXT_ACTION_ITERATIONS):\n        phase = state[\"phase\"]\n        config = PHASE_CONFIG.get(phase, {\"type\": \"noop\"})\n        phase_type = config.get(\"type\", \"noop\")\n\n        # --- DONE ---\n        if phase == \"DONE\":\n            print(yaml.dump(\n                {\"action\": \"done\", \"message\": \"Pipeline complete\"},\n                default_flow_style=False, sort_keys=False), end=\"\")\n            return\n\n        # --- Noop: advance and loop ---\n        if phase_type == \"noop\":\n            next_phase, summary = advance(state)\n            state[\"phase\"] = next_phase\n            _save_state(state)\n            print(summary, file=sys.stderr)\n            continue\n\n        # --- Script: check dispatch marker ---\n        if phase_type == \"script\":\n            if os.path.exists(DISPATCH_MARKER):\n                with open(DISPATCH_MARKER) as f:\n                    marker_phase = f.read().strip()\n                if marker_phase == phase:\n                    os.remove(DISPATCH_MARKER)\n                    next_phase, summary = advance(state)\n                    state[\"phase\"] = next_phase\n                    _save_state(state)\n                    print(summary, file=sys.stderr)\n                    continue\n                else:\n                    os.remove(DISPATCH_MARKER)\n            print(yaml.dump(\n                {\"action\": \"run_script\", \"phase\": phase,\n                 \"message\": f\"{phase}: run-phase\"},\n                default_flow_style=False, sort_keys=False), end=\"\")\n            return\n\n        # --- Agent: compute next wave ---\n        if phase_type == \"agent\":\n            ids_file = config.get(\"ids_file\", \"\")\n            all_ids = _read_ids(ids_file)\n            poll_phase = config.get(\"poll_phase\", \"\")\n\n            phases_to_check = [poll_phase] if poll_phase else []\n            for p in config.get(\"parallel\", []):\n                if p.get(\"poll_phase\"):\n                    phases_to_check.append(p[\"poll_phase\"])\n\n            remaining = []\n            for strat_id in all_ids:\n                for pphase in phases_to_check:\n                    if check_id(pphase, strat_id) == \"pending\":\n                        remaining.append(strat_id)\n                        break\n\n            if not remaining:\n                if config.get(\"post_verify\"):\n                    _run_script(config[\"post_verify\"])\n                next_phase, summary = advance(state)\n                state[\"phase\"] = next_phase\n                _save_state(state)\n                print(summary, file=sys.stderr)\n                continue\n\n            max_concurrent = int(state.get(\"batch_size\", 25))\n            n_parallel = len(config.get(\"parallel\", []))\n            wave_size = max(1, max_concurrent // (1 + n_parallel))\n\n            wave_ids = remaining[:wave_size]\n            wave_num = 1 + (len(all_ids) - len(remaining)) // wave_size\n            total_waves = max(1, -(-len(all_ids) // wave_size))\n\n            if config.get(\"pre_script\"):\n                for strat_id in wave_ids:\n                    cmd = config[\"pre_script\"].replace(\"{ID}\", strat_id)\n                    _run_script(cmd)\n\n            _write_ids(WAVE_IDS_FILE, wave_ids)\n\n            agents = []\n            for strat_id in wave_ids:\n                entry = {}\n                if config.get(\"subagent_type\"):\n                    entry[\"subagent_type\"] = config[\"subagent_type\"]\n                entry[\"prompt_file\"] = config[\"prompt\"]\n                var_lines = []\n                for k, v in config.get(\"vars\", {}).items():\n                    var_lines.append(\n                        f\"{k}={v.replace('{ID}', strat_id)}\")\n                entry[\"vars\"] = \"\\n\".join(var_lines) + \"\\n\"\n                agents.append(entry)\n\n                for par in config.get(\"parallel\", []):\n                    pentry = {}\n                    if par.get(\"subagent_type\"):\n                        pentry[\"subagent_type\"] = par[\"subagent_type\"]\n                    pentry[\"prompt_file\"] = par[\"prompt\"]\n                    pvar_lines = []\n                    for k, v in par.get(\"vars\", {}).items():\n                        pvar_lines.append(\n                            f\"{k}={v.replace('{ID}', strat_id)}\")\n                    pentry[\"vars\"] = \"\\n\".join(pvar_lines) + \"\\n\"\n                    agents.append(pentry)\n\n            msg = (f\"{phase}: wave {wave_num}/{total_waves}\"\n                   f\" ({len(wave_ids)} IDs)\")\n            output = {\n                \"action\": \"launch_wave\",\n                \"phase\": phase,\n                \"message\": msg,\n                \"agents\": agents,\n            }\n            print(yaml.dump(output, Dumper=_BlockDumper,\n                            default_flow_style=False, sort_keys=False),\n                  end=\"\")\n            return\n\n    print(f\"next-action: exceeded {MAX_NEXT_ACTION_ITERATIONS} iterations\"\n          f\" at phase {state['phase']}\", file=sys.stderr)\n    sys.exit(1)\n\n\ndef cmd_wait_for_wave(args):\n    if not os.path.exists(WAVE_IDS_FILE):\n        print(\"wait-for-wave: no wave file found\"\n              f\" ({WAVE_IDS_FILE}). Run next-action first.\",\n              file=sys.stderr)\n        sys.exit(1)\n\n    wave_ids = _read_ids(WAVE_IDS_FILE)\n    if not wave_ids:\n        print(\"wait-for-wave: wave file is empty.\"\n              \" All agents may already be complete.\",\n              file=sys.stderr)\n        return\n\n    state = _load_state()\n    phase = state[\"phase\"]\n    config = PHASE_CONFIG.get(phase, {\"type\": \"noop\"})\n\n    poll_phase = config.get(\"poll_phase\")\n    if not poll_phase:\n        print(f\"wait-for-wave: phase {phase} has no poll_phase\",\n              file=sys.stderr)\n        sys.exit(1)\n\n    cmd_parts = [\n        sys.executable,\n        os.path.join(os.path.dirname(__file__),\n                     \"check_decompose_progress.py\"),\n        \"--wait\",\n        \"--max-wait\", \"90\",\n        \"--phase\", poll_phase,\n    ]\n    for p in config.get(\"parallel\", []):\n        if p.get(\"poll_phase\"):\n            cmd_parts.extend([\"--also-phase\", p[\"poll_phase\"]])\n    if not state.get(\"headless\", True):\n        cmd_parts.append(\"--fast-poll\")\n    cmd_parts.extend([\"--id-file\", WAVE_IDS_FILE])\n\n    result = subprocess.run(cmd_parts)\n    if result.returncode == 0:\n        return\n    if result.returncode == 3:\n        print(\"Re-run: python3 scripts/pipeline_state.py wait-for-wave\")\n        sys.exit(3)\n    print(f\"wait-for-wave: check_decompose_progress.py exited with\"\n          f\" code {result.returncode}\", file=sys.stderr)\n    sys.exit(result.returncode)\n\n\ndef _check_agent_phase_complete(config):\n    ids_file = config.get(\"ids_file\")\n    poll_phase = config.get(\"poll_phase\")\n    if not ids_file or not poll_phase:\n        return True\n    ids = _read_ids(ids_file)\n    if not ids:\n        return True\n    from check_decompose_progress import check_id\n    phases_to_check = [poll_phase]\n    for p in config.get(\"parallel\", []):\n        if p.get(\"poll_phase\"):\n            phases_to_check.append(p[\"poll_phase\"])\n    for phase in phases_to_check:\n        for strat_id in ids:\n            if check_id(phase, strat_id) == \"pending\":\n                return False\n    return True\n\n\ndef cmd_advance(args):\n    dry_run = \"--dry-run\" in args\n    state = _load_state()\n    phase = state[\"phase\"]\n    config = PHASE_CONFIG.get(phase, {\"type\": \"noop\"})\n    phase_type = config.get(\"type\", \"noop\")\n    if phase_type == \"script\" and not dry_run:\n        if not os.path.exists(DISPATCH_MARKER):\n            print(f\"advance: script phase {phase} was not dispatched.\"\n                  \" Run: python3 scripts/pipeline_state.py next-action\",\n                  file=sys.stderr)\n            sys.exit(1)\n        with open(DISPATCH_MARKER) as f:\n            marker_phase = f.read().strip()\n        os.remove(DISPATCH_MARKER)\n        if marker_phase != phase:\n            print(f\"advance: dispatch marker is for {marker_phase},\"\n                  f\" not current phase {phase}\", file=sys.stderr)\n            sys.exit(1)\n    if phase_type == \"agent\" and not dry_run:\n        if not _check_agent_phase_complete(config):\n            print(f\"advance: agent phase {phase} has pending agents.\"\n                  f\" Run: python3 scripts/pipeline_state.py\"\n                  f\" wait-for-wave\",\n                  file=sys.stderr)\n            sys.exit(1)\n    next_phase, summary = advance(state, dry_run=dry_run)\n    if not dry_run:\n        state[\"phase\"] = next_phase\n        _save_state(state)\n    print(summary)\n\n\ndef cmd_set(args):\n    if not args:\n        print(\"Usage: set key=value ...\", file=sys.stderr)\n        sys.exit(1)\n    state = _load_state()\n    for arg in args:\n        if \"=\" not in arg:\n            print(f\"Invalid key=value: {arg}\", file=sys.stderr)\n            sys.exit(1)\n        k, v = arg.split(\"=\", 1)\n        if v.isdigit():\n            v = int(v)\n        elif v.lower() in (\"true\", \"false\"):\n            v = v.lower() == \"true\"\n        state[k] = v\n    _save_state(state)\n\n\ndef cmd_get(args):\n    if not args:\n        print(\"Usage: get <key>\", file=sys.stderr)\n        sys.exit(1)\n    state = _load_state()\n    val = state.get(args[0])\n    if val is None:\n        sys.exit(1)\n    print(val)\n\n\ndef cmd_status(args):\n    state = _load_state()\n    print(yaml.dump(state, default_flow_style=False, sort_keys=False),\n          end=\"\")\n\n\ndef cmd_diagnose(args):\n    state = _load_state()\n    phase = state[\"phase\"]\n    print(f\"Phase: {phase}\")\n    print(f\"Batch: {state.get('batch', 0)}/{state.get('total_batches', 0)}\")\n    print(f\"Revise cycle: {state.get('revise_cycle', 0)}/2\")\n    print(f\"Retry cycle: {state.get('retry_cycle', 0)}/1\")\n\n    id_files = [\n        \"tmp/pipeline-all-ids.txt\",\n        \"tmp/pipeline-active-ids.txt\",\n        \"tmp/pipeline-revise-ids.txt\",\n        \"tmp/pipeline-retry-ids.txt\",\n    ]\n    print(\"\\nID files:\")\n    for f in id_files:\n        if os.path.exists(f):\n            ids = _read_ids(f)\n            print(f\"  {f}: {len(ids)} IDs\")\n        else:\n            print(f\"  {f}: (missing)\")\n\n    active = _read_ids(\"tmp/pipeline-active-ids.txt\")\n    if active:\n        missing_strat = []\n        missing_decomp = []\n        error_ids = []\n        for strat_id in active:\n            if not os.path.exists(f\"artifacts/strat-tasks/{strat_id}.md\"):\n                missing_strat.append(strat_id)\n            decomp = f\"artifacts/epic-tasks/{strat_id}-decomposition.md\"\n            if not os.path.exists(decomp):\n                missing_decomp.append(strat_id)\n            review = f\"artifacts/epic-reviews/{strat_id}-decomp-review.md\"\n            if os.path.exists(review):\n                try:\n                    from artifact_utils import read_frontmatter\n                    data, _ = read_frontmatter(review)\n                    if data and data.get(\"error\"):\n                        error_ids.append(strat_id)\n                except Exception:\n                    pass\n        print(f\"\\nActive IDs: {len(active)}\")\n        if missing_strat:\n            print(f\"  Missing strategy files: {', '.join(missing_strat)}\")\n        if missing_decomp:\n            print(f\"  Missing decomposition files: {', '.join(missing_decomp)}\")\n        if error_ids:\n            print(f\"  Error IDs: {', '.join(error_ids)}\")\n\n\nDISPATCH_LOOP = \"\"\"\\\nResume the dispatch loop:\n  1. python3 scripts/pipeline_state.py next-action\n  2. If action == done: exit loop, run teardown\n  3. If action == run_script: python3 scripts/pipeline_state.py run-phase, then go to 1\n  4. If action == launch_wave:\n     a. For each agent in agents: launch background Agent(prompt=vars + \"\\\\n\\\\nRead \" + prompt_file + \" and follow all instructions exactly.\", subagent_type if present)\n     b. python3 scripts/pipeline_state.py wait-for-wave (re-run on exit 3), then go to 1\"\"\"\n\n\ndef cmd_dispatch_context(args):\n    if not os.path.exists(STATE_FILE):\n        return\n    state = _load_state()\n    phase = state[\"phase\"]\n    if phase not in PHASES:\n        print(f\"[PIPELINE STATE RECOVERY] Setup in progress (phase: {phase})\")\n        print(\"Setup is not yet complete. Re-read SKILL.md\"\n              \" (skills/epic-decompose/SKILL.md) and resume\"\n              \" the setup steps from where you left off.\")\n        return\n    if phase == \"DONE\":\n        print(\"[PIPELINE STATE RECOVERY] Pipeline complete (phase: DONE)\")\n        return\n    config = PHASE_CONFIG.get(phase, {\"type\": \"noop\"})\n    phase_type = config.get(\"type\", \"noop\")\n    print(f\"[PIPELINE STATE RECOVERY] Current phase: {phase}\"\n          f\" (type: {phase_type})\")\n    print(f\"Batch: {state.get('batch', 0)}/{state.get('total_batches', 0)}\")\n    print()\n    print(DISPATCH_LOOP)\n\n\ndef cmd_post_compact_hook(args):\n    if not os.environ.get(\"EPIC_CREATOR_ENABLE_CONTEXT_HOOK\"):\n        return\n    cmd_dispatch_context(args)\n\n\nCOMMANDS = {\n    \"init\": cmd_init,\n    \"get-phase\": cmd_get_phase,\n    \"set-phase\": cmd_set_phase,\n    \"get-phase-config\": cmd_get_phase_config,\n    \"run-phase\": cmd_run_phase,\n    \"set-wave\": cmd_set_wave,\n    \"next-action\": cmd_next_action,\n    \"wait-for-wave\": cmd_wait_for_wave,\n    \"advance\": cmd_advance,\n    \"set\": cmd_set,\n    \"get\": cmd_get,\n    \"status\": cmd_status,\n    \"diagnose\": cmd_diagnose,\n    \"dispatch-context\": cmd_dispatch_context,\n    \"post-compact-hook\": cmd_post_compact_hook,\n}\n\nif __name__ == \"__main__\":\n    if len(sys.argv) < 2 or sys.argv[1] not in COMMANDS:\n        print(f\"Commands: {', '.join(COMMANDS)}\", file=sys.stderr)\n        sys.exit(1)\n    COMMANDS[sys.argv[1]](sys.argv[2:])\n","numLines":866,"startLine":1,"totalLines":866}},"tool_result_meta":[{"id":"chatcmpl-tool-975b2fc0d7f2264e","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}]}
