eturn \"pending\"\n52\t        epic_count = data.get(\"epic_count\")\n53\t        if not epic_count:\n54\t            return \"pending\"\n55\t        # Wait until the agent is done writing, not just until the summary\n56\t        # exists.  The summary is written first (Step 8a) and epic files\n57\t        # follow (Step 8b), then Step 8c edits them; advancing early hands\n58\t        # REVIEW_DECOMP a partially written decomposition.\n59\t        if not _decompose_complete(strat_id, data):\n60\t            return \"pending\"\n61\t        return \"completed\"\n62\t    if phase == \"review_decomp\":\n63\t        # The review agent writes the body first and sets frontmatter via\n64\t        # frontmatter.py seconds later. A file that exists without parseable\n65\t        # frontmatter is mid-write, not failed — same reasoning as the\n66\t        # decompose branch above. Returning \"error\" here released the\n67\t        # wait-for-wave barrier early (ERRORS=1, pending=0 -> NEXT_POLL=0) in\n68\t        # three cases of the 2026-08-19 eval run, letting the dispatcher\n69\t        # advance phases while the reviewer was still writing.\n70\t        try:\n71\t            data, _ = read_frontmatter(path)\n72\t        except Exception:\n73\t            return \"pending\"\n74\t        if not data:\n75\t            return \"pending\"\n76\t        if data.get(\"score\") is None:\n77\t            return \"pending\"\n78\t        if data.get(\"error\"):\n79\t            return \"error\"\n80\t    if phase == \"revise_decomp\":\n81\t        # Same body-then-frontmatter write pattern as the review agent.\n82\t        try:\n83\t            data, _ = read_frontmatter(path)\n84\t        except Exception:\n85\t            return \"pending\"\n86\t        if not data:\n87\t            return \"pending\"\n88\t        # revised can be true (changes made) or false (no changes needed).\n89\t        # Either value means the agent finished. Only absent/None = pending.\n90\t        if data.get(\"revised\") is not None:\n91\t            return \"completed\"\n92\t        return \"pending\"\n93\t    return \"completed\"\n94\t\n95\t\n96\tdef _check_phase(phase, ids, fast):\n97\t    \"\"\"Check one phase and return (completed, errors, pending, total, next_poll).\"\"\"\n98\t    completed = 0\n99\t    errors = 0\n100\t    pending_ids = []\n101\t\n102\t    for strat_id in ids:\n103\t        result = check_id(phase, strat_id)\n104\t        if result == \"completed\":\n105\t            completed += 1\n106\t        elif result == \"error\":\n107\t            errors += 1\n108\t        else:\n109\t            pending_ids.append(strat_id)\n110\t\n111\t    total = len(ids)\n112\t    pending = len(pending_ids)\n113\t\n114\t    if pending == 0:\n115\t        next_poll = 0\n116\t    elif fast:\n117\t        next_poll = 15\n118\t    elif completed / total >= 0.75:\n119\t        next_poll = 15\n120\t    elif completed / total >= 0.5:\n121\t        next_poll = 30\n122\t    else:\n123\t        next_poll = 60\n124\t\n125\t    return completed, errors, pending, total, next_poll\n126\t\n127\t\n128\tdef _format_status(phase, completed, errors, pending, total, next_poll):\n129\t    \"\"\"Format a status line for one phase.\"\"\"\n130\t    parts = [f\"COMPLETED={completed}/{total}\"]\n131\t    if pending:\n132\t        parts.append(f\"PENDING={pending}\")\n133\t    if errors:\n134\t        parts.append(f\"ERRORS={errors}\")\n135\t    parts.append(f\"NEXT_POLL={next_poll}\")\n136\t    return f\"{phase}: {', '.join(parts)}\"\n137\t\n138\t\n139\tdef _detect_fast(explicit_flag):\n140\t    \"\"\"Return True if fast-poll should be used.\"\"\"\n141\t    if explicit_flag:\n142\t        return True\n143\t    for cfg in (\"tmp/decompose-config.yaml\", \"tmp/pipeline-state.yaml\"):\n144\t        if os.path.exists(cfg):\n145\t            try:\n146\t                with open(cfg) as f:\n147\t                    data = yaml.safe_load(f)\n148\t                if data and data.get(\"headless\") is F