{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-bde5e88c00c2607d","type":"tool_result","content":"1\t\"\"\"Artifact schema definitions, frontmatter read/write/validate.\n2\t\n3\tOwns all structured metadata for strategy and epic decomposition artifacts.\n4\tScripts and skills use this module instead of regex-parsing markdown prose.\n5\t\n6\tFrontmatter is stored as YAML between --- delimiters at the top of markdown files.\n7\t\"\"\"\n8\t\n9\timport os\n10\timport re\n11\timport sys\n12\t\n13\timport yaml\n14\t\n15\t\n16\t# ─── Schema Definitions ────────────────────────────────────────────────────────\n17\t\n18\t# Each schema is a dict of field_name -> field_spec.\n19\t# field_spec keys:\n20\t#   type:     \"string\" | \"int\" | \"bool\" | \"list\" | \"dict\"\n21\t#   required: bool (default False)\n22\t#   enum:     list of allowed values (optional)\n23\t#   pattern:  regex pattern the value must match (optional, strings only)\n24\t#   default:  default value when not provided (optional)\n25\t#   fields:   nested schema for type=\"dict\" (optional)\n26\t\n27\tSCHEMAS = {\n28\t    \"strat-task\": {\n29\t        \"strat_id\": {\n30\t            \"type\": \"string\",\n31\t            \"required\": True,\n32\t            \"pattern\": r\"^RHAISTRAT-\\d+$\",\n33\t        },\n34\t        \"title\": {\n35\t            \"type\": \"string\",\n36\t            \"required\": True,\n37\t        },\n38\t        \"status\": {\n39\t            \"type\": \"string\",\n40\t            \"required\": False,\n41\t            \"default\": \"\",\n42\t        },\n43\t        \"priority\": {\n44\t            \"type\": \"string\",\n45\t            \"required\": False,\n46\t            \"default\": \"\",\n47\t        },\n48\t        \"labels\": {\n49\t            \"type\": \"list\",\n50\t            \"required\": False,\n51\t            \"default\": [],\n52\t        },\n53\t        \"links\": {\n54\t            \"type\": \"list\",\n55\t            \"required\": False,\n56\t            \"default\": [],\n57\t        },\n58\t        \"attachment_source\": {\n59\t            \"type\": \"string\",\n60\t            \"required\": False,\n61\t            \"default\": \"\",\n62\t        },\n63\t    },\n64\t    \"epic-task\": {\n65\t        \"epic_id\": {\n66\t            \"type\": \"string\",\n67\t            \"required\": True,\n68\t        },\n69\t        \"title\": {\n70\t            \"type\": \"string\",\n71\t            \"required\": True,\n72\t        },\n73\t        \"parent_strat\": {\n74\t            \"type\": \"string\",\n75\t            \"required\": True,\n76\t            \"pattern\": r\"^RHAISTRAT-\\d+$\",\n77\t        },\n78\t        \"component\": {\n79\t            \"type\": \"string\",\n80\t            \"required\": True,\n81\t        },\n82\t        \"team\": {\n83\t            \"type\": \"string\",\n84\t            \"required\": True,\n85\t        },\n86\t        \"type\": {\n87\t            \"type\": \"string\",\n88\t            \"required\": True,\n89\t            \"enum\": [\"Implementation\", \"Investigation\"],\n90\t        },\n91\t        \"implementation_type\": {\n92\t            \"type\": \"string\",\n93\t            \"required\": False,\n94\t            \"enum\": [\"docs-authoring\", \"konflux-onboarding\",\n95\t                     \"license-validation\", \"repo-onboarding\"],\n96\t            \"default\": None,\n97\t        },\n98\t        \"priority\": {\n99\t            \"type\": \"string\",\n100\t            \"required\": True,\n101\t            \"enum\": [\"P0\", \"P1\", \"P2\"],\n102\t        },\n103\t        \"dependencies\": {\n104\t            \"type\": \"list\",\n105\t            \"required\": False,\n106\t            \"default\": [],\n107\t        },\n108\t        \"ai_signals\": {\n109\t            \"type\": \"dict\",\n110\t            \"required\": False,\n111\t            \"default\": None,\n112\t            \"fields\": {\n113\t                \"change_specificity\":  {\"type\": \"int\", \"required\": False, \"default\": 0},\n114\t                \"pattern_precedent\":   {\"type\": \"int\", \"required\": False, \"default\": 0},\n115\t                \"adapter_pattern\":     {\"type\": \"int\", \"required\": False, \"default\": 0},\n116\t                \"existing_foundation\": {\"type\": \"int\", \"required\": False, \"default\": 0},\n117\t                \"open_questions\":      {\"type\": \"int\", \"required\": False, \"default\": 0},\n118\t                \"external_dependency\": {\"type\": \"int\", \"required\": False, \"default\": 0},\n119\t                \"human_process_gates\": {\"type\": \"int\", \"required\": False, \"default\": 0},\n120\t                \"repo_access\":         {\"type\": \"int\", \"required\": False, \"default\": 0},\n121\t                \"architecture_claims\": {\"type\": \"int\", \"required\": False, \"default\": 0},\n122\t            },\n123\t        },\n124\t        # Investigation epics use this set instead of ai_signals. The\n125\t        # Implementation signals above penalize the *defining* traits of an\n126\t        # investigation (open questions, no foundation), so they systematically\n127\t        # mis-route investigations to Low. These five predict, at decomposition\n128\t        # time, whether the AI skill can resolve the unknowns (assign to skill)\n129\t        # or they need a person. Scored +1/0 for positives, 0/-1/-2 for blockers.\n130\t        \"investigation_signals\": {\n131\t            \"type\": \"dict\",\n132\t            \"required\": False,\n133\t            \"default\": None,\n134\t            \"fields\": {\n135\t                # Positives: is it well-posed, readable, and runnable?\n136\t                \"question_specificity\":        {\"type\": \"int\", \"required\": False, \"default\": 0, \"enum\": [-1, 0, 1]},\n137\t                \"source_accessibility\":        {\"type\": \"int\", \"required\": False, \"default\": 0, \"enum\": [0, 1]},\n138\t                \"local_runnability\":           {\"type\": \"int\", \"required\": False, \"default\": 0, \"enum\": [0, 1]},\n139\t                # Blockers (0/-1/-2): does resolving it need a cluster/hardware\n140\t                # or a human decision the AI can't make?\n141\t                \"cluster_hardware_dependence\": {\"type\": \"int\", \"required\": False, \"default\": 0, \"enum\": [-2, -1, 0]},\n142\t                \"human_judgment_required\":     {\"type\": \"int\", \"required\": False, \"default\": 0, \"enum\": [-2, -1, 0]},\n143\t            },\n144\t        },\n145\t        \"ai_implementability\": {\n146\t            \"type\": \"string\",\n147\t            \"required\": False,\n148\t            \"enum\": [\"High\", \"Medium\", \"Low\"],\n149\t            \"default\": None,\n150\t        },\n151\t        \"ai_implementability_score\": {\n152\t            \"type\": \"int\",\n153\t            \"required\": False,\n154\t            \"default\": None,\n155\t        },\n156\t        \"jira_key\": {\n157\t            \"type\": \"string\",\n158\t            \"required\": False,\n159\t            \"pattern\": r\"^[A-Z][A-Z0-9_]*-\\d+$\",\n160\t            \"default\": None,\n161\t        },\n162\t        \"branch\": {\n163\t            \"type\": \"string\",\n164\t            \"required\": False,\n165\t            \"default\": None,\n166\t        },\n167\t        \"gated_by\": {\n168\t            \"type\": \"string\",\n169\t            \"required\": False,\n170\t            \"default\": None,\n171\t        },\n172\t        \"gate_failure_impact\": {\n173\t            \"type\": \"dict\",\n174\t            \"required\": False,\n175\t            \"default\": None,\n176\t            \"fields\": {\n177\t                \"action\": {\n178\t                    \"type\": \"string\",\n179\t                    \"required\": False,\n180\t                    \"enum\": [\"rewrite\", \"remove\", \"add_remediation\"],\n181\t                    \"default\": None,\n182\t                },\n183\t                \"fallback_approach\": {\n184\t                    \"type\": \"string\",\n185\t                    \"required\": False,\n186\t                    \"default\": None,\n187\t                },\n188\t            },\n189\t        },\n190\t    },\n191\t    \"decomp-summary\": {\n192\t        \"parent_strat\": {\n193\t            \"type\": \"string\",\n194\t            \"required\": True,\n195\t            \"pattern\": r\"^RHAISTRAT-\\d+$\",\n196\t        },\n197\t        \"epic_count\": {\n198\t            \"type\": \"int\",\n199\t            \"required\": True,\n200\t        },\n201\t        \"critical_path_length\": {\n202\t            \"type\": \"int\",\n203\t            \"required\": True,\n204\t        },\n205\t        \"decompose_complete\": {\n206\t            \"type\": \"bool\",\n207\t            \"required\": False,\n208\t            \"default\": False,\n209\t        },\n210\t        \"revised\": {\n211\t            \"type\": \"bool\",\n212\t            \"required\": False,\n213\t            \"default\": False,\n214\t        },\n215\t        \"triage\": {\n216\t            \"type\": \"string\",\n217\t            \"required\": False,\n218\t            \"enum\": [\"below-threshold\", \"docs-only\"],\n219\t            \"default\": None,\n220\t        },\n221\t        \"triage_rationale\": {\n222\t            \"type\": \"string\",\n223\t            \"required\": False,\n224\t            \"default\": None,\n225\t        },\n226\t    },\n227\t    \"decomp-review\": {\n228\t        \"strat_id\": {\n229\t            \"type\": \"string\",\n230\t            \"required\": True,\n231\t            \"pattern\": r\"^RHAISTRAT-\\d+$\",\n232\t        },\n233\t        \"score\": {\n234\t            \"type\": \"int\",\n235\t            \"required\": True,\n236\t        },\n237\t        \"pass\": {\n238\t            \"type\": \"bool\",\n239\t            \"required\": True,\n240\t        },\n241\t        \"recommendation\": {\n242\t            \"type\": \"string\",\n243\t            \"required\": True,\n244\t            \"enum\": [\"accept\", \"revise\"],\n245\t        },\n246\t        \"issues\": {\n247\t            \"type\": \"list\",\n248\t            \"required\": False,\n249\t            \"default\": [],\n250\t        },\n251\t        \"error\": {\n252\t            \"type\": \"string\",\n253\t            \"required\": False,\n254\t            \"default\": None,\n255\t        },\n256\t    },\n257\t}\n258\t\n259\t\n260\t# ─── Validation ─────────────────────────────────────────────────────────────────\n261\t\n262\tclass ValidationError(Exception):\n263\t    \"\"\"Raised when frontmatter fails schema validation.\"\"\"\n264\t    pass\n265\t\n266\t\n267\tdef _validate_field(name, value, spec, path=\"\"):\n268\t    \"\"\"Validate a single field against its spec. Returns list of errors.\"\"\"\n269\t    errors = []\n270\t    full_name = f\"{path}.{name}\" if path else name\n271\t\n272\t    if value is None:\n273\t        if spec.get(\"required\", False) and \"default\" not in spec:\n274\t            errors.append(f\"Missing required field: {full_name}\")\n275\t        return errors\n276\t\n277\t    expected_type = spec.get(\"type\", \"string\")\n278\t\n279\t    if expected_type == \"string\":\n280\t        if not isinstance(value, str):\n281\t            errors.append(\n282\t                f\"{full_name}: expected string, got {type(value).__name__}\")\n283\t            return errors\n284\t        if \"enum\" in spec and value not in spec[\"enum\"]:\n285\t            errors.append(\n286\t                f\"{full_name}: '{value}' not in {spec['enum']}\")\n287\t        if \"pattern\" in spec and not re.match(spec[\"pattern\"], value):\n288\t            errors.append(\n289\t                f\"{full_name}: '{value}' does not match {spec['pattern']}\")\n290\t\n291\t    elif expected_type == \"int\":\n292\t        if not isinstance(value, int) or isinstance(value, bool):\n293\t            errors.append(\n294\t                f\"{full_name}: expected int, got {type(value).__name__}\")\n295\t        elif \"enum\" in spec and value not in spec[\"enum\"]:\n296\t            errors.append(\n297\t                f\"{full_name}: {value} not in {spec['enum']}\")\n298\t\n299\t    elif expected_type == \"bool\":\n300\t        if not isinstance(value, bool):\n301\t            errors.append(\n302\t                f\"{full_name}: expected bool, got {type(value).__name__}\")\n303\t\n304\t    elif expected_type == \"list\":\n305\t        if not isinstance(value, list):\n306\t            errors.append(\n307\t                f\"{full_name}: expected list, got {type(value).__name__}\")\n308\t\n309\t    elif expected_type == \"dict\":\n310\t        if not isinstance(value, dict):\n311\t            errors.append(\n312\t                f\"{full_name}: expected dict, got {type(value).__name__}\")\n313\t            return errors\n314\t        nested_schema = spec.get(\"fields\", {})\n315\t        for key in value:\n316\t            if key not in nested_schema:\n317\t                errors.append(f\"{full_name}: unknown field '{key}'\")\n318\t        for field_name, field_spec in nested_schema.items():\n319\t            errors.extend(_validate_field(\n320\t                field_name, value.get(field_name), field_spec, full_name))\n321\t\n322\t    return errors\n323\t\n324\t\n325\tdef validate(data, schema_type):\n326\t    \"\"\"Validate frontmatter data against a schema.\n327\t\n328\t    Returns list of error strings (empty if valid).\n329\t    Raises ValueError if schema_type is unknown.\n330\t    \"\"\"\n331\t    if schema_type not in SCHEMAS:\n332\t        raise ValueError(\n333\t            f\"Unknown schema type: {schema_type}. \"\n334\t            f\"Valid types: {list(SCHEMAS.keys())}\")\n335\t\n336\t    schema = SCHEMAS[schema_type]\n337\t    errors = []\n338\t\n339\t    for key in data:\n340\t        if key not in schema:\n341\t            errors.append(f\"Unknown field: {key}\")\n342\t\n343\t    for field_name, field_spec in schema.items():\n344\t        errors.extend(_validate_field(\n345\t            field_name, data.get(field_name), field_spec))\n346\t\n347\t    return errors\n348\t\n349\t\n350\tdef apply_defaults(data, schema_type):\n351\t    \"\"\"Apply default values for missing optional fields. Modifies in-place.\"\"\"\n352\t    schema = SCHEMAS[schema_type]\n353\t    for field_name, field_spec in schema.items():\n354\t        if field_name not in data and \"default\" in field_spec:\n355\t            data[field_name] = field_spec[\"default\"]\n356\t        if field_spec.get(\"type\") == \"dict\" and field_name in data:\n357\t            nested = data[field_name]\n358\t            if isinstance(nested, dict):\n359\t                for nested_name, nested_spec in \\\n360\t                        field_spec.get(\"fields\", {}).items():\n361\t                    if nested_name not in nested and \\\n362\t                            \"default\" in nested_spec:\n363\t                        nested[nested_name] = nested_spec[\"default\"]\n364\t    return data\n365\t\n366\t\n367\tdef get_schema_yaml(schema_type):\n368\t    \"\"\"Return the schema definition as a YAML string for display.\"\"\"\n369\t    if schema_type not in SCHEMAS:\n370\t        raise ValueError(\n371\t            f\"Unknown schema type: {schema_type}. \"\n372\t            f\"Valid types: {list(SCHEMAS.keys())}\")\n373\t\n374\t    schema = SCHEMAS[schema_type]\n375\t    output = {\"required\": {}, \"optional\": {}}\n376\t\n377\t    for name, spec in schema.items():\n378\t        entry = {\"type\": spec[\"type\"]}\n379\t        if \"enum\" in spec:\n380\t            entry[\"enum\"] = spec[\"enum\"]\n381\t        if \"pattern\" in spec:\n382\t            entry[\"pattern\"] = spec[\"pattern\"]\n383\t        if \"default\" in spec:\n384\t            entry[\"default\"] = spec[\"default\"]\n385\t        if spec.get(\"type\") == \"dict\" and \"fields\" in spec:\n386\t            entry[\"fields\"] = {}\n387\t            for fname, fspec in spec[\"fields\"].items():\n388\t                fentry = {\"type\": fspec[\"type\"]}\n389\t                if \"enum\" in fspec:\n390\t                    fentry[\"enum\"] = fspec[\"enum\"]\n391\t                entry[\"fields\"][fname] = fentry\n392\t\n393\t        if spec.get(\"required\", False):\n394\t            output[\"required\"][name] = entry\n395\t        else:\n396\t            output[\"optional\"][name] = entry\n397\t\n398\t    return yaml.dump(output, default_flow_style=False, sort_keys=False)\n399\t\n400\t\n401\t# ─── Frontmatter Read/Write ────────────────────────────────────────────────────\n402\t\n403\t_FRONTMATTER_RE = re.compile(\n404\t    r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n405\t\n406\t\n407\tdef read_frontmatter(path):\n408\t    \"\"\"Read and parse YAML frontmatter from a markdown file.\n409\t\n410\t    Returns:\n411\t        (data_dict, body_string) — frontmatter as dict, remainder as string.\n412\t        Returns ({}, full_content) if no frontmatter found.\n413\t    \"\"\"\n414\t    if not os.path.exists(path):\n415\t        return {}, \"\"\n416\t\n417\t    with open(path, encoding=\"utf-8\") as f:\n418\t        content = f.read()\n419\t\n420\t    match = _FRONTMATTER_RE.match(content)\n421\t    if not match:\n422\t        return {}, content\n423\t\n424\t    yaml_str = match.group(1)\n425\t    body = content[match.end():]\n426\t\n427\t    data = yaml.safe_load(yaml_str)\n428\t    if not isinstance(data, dict):\n429\t        return {}, content\n430\t\n431\t    return data, body\n432\t\n433\t\n434\tdef read_frontmatter_validated(path, schema_type):\n435\t    \"\"\"Read frontmatter and validate against schema.\n436\t\n437\t    Raises:\n438\t        ValidationError: if frontmatter fails validation\n439\t        FileNotFoundError: if file doesn't exist\n440\t    \"\"\"\n441\t    data, body = read_frontmatter(path)\n442\t    if not data:\n443\t        raise ValidationError(f\"No frontmatter found in {path}\")\n444\t\n445\t    apply_defaults(data, schema_type)\n446\t    errors = validate(data, schema_type)\n447\t    if errors:\n448\t        raise ValidationError(\n449\t            f\"Frontmatter validation failed in {path}:\\n\"\n450\t            + \"\\n\".join(f\"  - {e}\" for e in errors))\n451\t\n452\t    return data, body\n453\t\n454\t\n455\tdef write_frontmatter(path, data, schema_type):\n456\t    \"\"\"Write/update YAML frontmatter on a markdown file.\n457\t\n458\t    Validates data against the schema before writing. Preserves the\n459\t    markdown body below the frontmatter. Creates the file if it doesn't\n460\t    exist (with empty body).\n461\t\n462\t    Raises:\n463\t        ValidationError: if data fails schema validation\n464\t    \"\"\"\n465\t    apply_defaults(data, schema_type)\n466\t    errors = validate(data, schema_type)\n467\t    if errors:\n468\t        raise ValidationError(\n469\t            f\"Frontmatter validation failed:\\n\"\n470\t            + \"\\n\".join(f\"  - {e}\" for e in errors))\n471\t\n472\t    body = \"\"\n473\t    if os.path.exists(path):\n474\t        _, body = read_frontmatter(path)\n475\t\n476\t    yaml_str = yaml.dump(data, default_flow_style=False, sort_keys=False,\n477\t                         allow_unicode=True)\n478\t    content = f\"---\\n{yaml_str}---\\n{body}\"\n479\t\n480\t    parent = os.path.dirname(path)\n481\t    if parent:\n482\t        os.makedirs(parent, exist_ok=True)\n483\t    with open(path, \"w\", encoding=\"utf-8\") as f:\n484\t        f.write(content)\n485\t\n486\t\n487\tdef update_frontmatter(path, updates, schema_type):\n488\t    \"\"\"Merge updates into existing frontmatter and rewrite.\n489\t\n490\t    Raises:\n491\t        ValidationError: if merged data fails validation\n492\t        FileNotFoundError: if file doesn't exist\n493\t    \"\"\"\n494\t    data, body = read_frontmatter(path)\n495\t    for key, value in updates.items():\n496\t        if isinstance(value, dict) and isinstance(data.get(key), dict):\n497\t            data[key].update(value)\n498\t        else:\n499\t            data[key] = value\n500\t\n501\t    apply_defaults(data, schema_type)\n502\t    errors = validate(data, schema_type)\n503\t    if errors:\n504\t        raise ValidationError(\n505\t            f\"Frontmatter validation failed after update in {path}:\\n\"\n506\t            + \"\\n\".join(f\"  - {e}\" for e in errors))\n507\t\n508\t    yaml_str = yaml.dump(data, default_flow_style=False, sort_keys=False,\n509\t                         allow_unicode=True)\n510\t    content = f\"---\\n{yaml_str}---\\n{body}\"\n511\t\n512\t    with open(path, \"w\", encoding=\"utf-8\") as f:\n513\t        f.write(content)\n514\t"}]},"parent_tool_use_id":null,"session_id":"ffc190d1-a457-4608-ad90-0fad47057ac1","uuid":"d7ea62a6-9168-4334-8527-21834adfbf5b","timestamp":"2026-10-09T13:59:06.767Z","tool_use_result":{"type":"text","file":{"filePath":"/private/var/folders/h5/l8qslbp55w5621qf9ngsh5jc0000gn/T/epic_case-021-real-pqc-base-image-compliance_0_yhs98llf/scripts/artifact_utils.py","content":"\"\"\"Artifact schema definitions, frontmatter read/write/validate.\n\nOwns all structured metadata for strategy and epic decomposition artifacts.\nScripts and skills use this module instead of regex-parsing markdown prose.\n\nFrontmatter is stored as YAML between --- delimiters at the top of markdown files.\n\"\"\"\n\nimport os\nimport re\nimport sys\n\nimport yaml\n\n\n# ─── Schema Definitions ────────────────────────────────────────────────────────\n\n# Each schema is a dict of field_name -> field_spec.\n# field_spec keys:\n#   type:     \"string\" | \"int\" | \"bool\" | \"list\" | \"dict\"\n#   required: bool (default False)\n#   enum:     list of allowed values (optional)\n#   pattern:  regex pattern the value must match (optional, strings only)\n#   default:  default value when not provided (optional)\n#   fields:   nested schema for type=\"dict\" (optional)\n\nSCHEMAS = {\n    \"strat-task\": {\n        \"strat_id\": {\n            \"type\": \"string\",\n            \"required\": True,\n            \"pattern\": r\"^RHAISTRAT-\\d+$\",\n        },\n        \"title\": {\n            \"type\": \"string\",\n            \"required\": True,\n        },\n        \"status\": {\n            \"type\": \"string\",\n            \"required\": False,\n            \"default\": \"\",\n        },\n        \"priority\": {\n            \"type\": \"string\",\n            \"required\": False,\n            \"default\": \"\",\n        },\n        \"labels\": {\n            \"type\": \"list\",\n            \"required\": False,\n            \"default\": [],\n        },\n        \"links\": {\n            \"type\": \"list\",\n            \"required\": False,\n            \"default\": [],\n        },\n        \"attachment_source\": {\n            \"type\": \"string\",\n            \"required\": False,\n            \"default\": \"\",\n        },\n    },\n    \"epic-task\": {\n        \"epic_id\": {\n            \"type\": \"string\",\n            \"required\": True,\n        },\n        \"title\": {\n            \"type\": \"string\",\n            \"required\": True,\n        },\n        \"parent_strat\": {\n            \"type\": \"string\",\n            \"required\": True,\n            \"pattern\": r\"^RHAISTRAT-\\d+$\",\n        },\n        \"component\": {\n            \"type\": \"string\",\n            \"required\": True,\n        },\n        \"team\": {\n            \"type\": \"string\",\n            \"required\": True,\n        },\n        \"type\": {\n            \"type\": \"string\",\n            \"required\": True,\n            \"enum\": [\"Implementation\", \"Investigation\"],\n        },\n        \"implementation_type\": {\n            \"type\": \"string\",\n            \"required\": False,\n            \"enum\": [\"docs-authoring\", \"konflux-onboarding\",\n                     \"license-validation\", \"repo-onboarding\"],\n            \"default\": None,\n        },\n        \"priority\": {\n            \"type\": \"string\",\n            \"required\": True,\n            \"enum\": [\"P0\", \"P1\", \"P2\"],\n        },\n        \"dependencies\": {\n            \"type\": \"list\",\n            \"required\": False,\n            \"default\": [],\n        },\n        \"ai_signals\": {\n            \"type\": \"dict\",\n            \"required\": False,\n            \"default\": None,\n            \"fields\": {\n                \"change_specificity\":  {\"type\": \"int\", \"required\": False, \"default\": 0},\n                \"pattern_precedent\":   {\"type\": \"int\", \"required\": False, \"default\": 0},\n                \"adapter_pattern\":     {\"type\": \"int\", \"required\": False, \"default\": 0},\n                \"existing_foundation\": {\"type\": \"int\", \"required\": False, \"default\": 0},\n                \"open_questions\":      {\"type\": \"int\", \"required\": False, \"default\": 0},\n                \"external_dependency\": {\"type\": \"int\", \"required\": False, \"default\": 0},\n                \"human_process_gates\": {\"type\": \"int\", \"required\": False, \"default\": 0},\n                \"repo_access\":         {\"type\": \"int\", \"required\": False, \"default\": 0},\n                \"architecture_claims\": {\"type\": \"int\", \"required\": False, \"default\": 0},\n            },\n        },\n        # Investigation epics use this set instead of ai_signals. The\n        # Implementation signals above penalize the *defining* traits of an\n        # investigation (open questions, no foundation), so they systematically\n        # mis-route investigations to Low. These five predict, at decomposition\n        # time, whether the AI skill can resolve the unknowns (assign to skill)\n        # or they need a person. Scored +1/0 for positives, 0/-1/-2 for blockers.\n        \"investigation_signals\": {\n            \"type\": \"dict\",\n            \"required\": False,\n            \"default\": None,\n            \"fields\": {\n                # Positives: is it well-posed, readable, and runnable?\n                \"question_specificity\":        {\"type\": \"int\", \"required\": False, \"default\": 0, \"enum\": [-1, 0, 1]},\n                \"source_accessibility\":        {\"type\": \"int\", \"required\": False, \"default\": 0, \"enum\": [0, 1]},\n                \"local_runnability\":           {\"type\": \"int\", \"required\": False, \"default\": 0, \"enum\": [0, 1]},\n                # Blockers (0/-1/-2): does resolving it need a cluster/hardware\n                # or a human decision the AI can't make?\n                \"cluster_hardware_dependence\": {\"type\": \"int\", \"required\": False, \"default\": 0, \"enum\": [-2, -1, 0]},\n                \"human_judgment_required\":     {\"type\": \"int\", \"required\": False, \"default\": 0, \"enum\": [-2, -1, 0]},\n            },\n        },\n        \"ai_implementability\": {\n            \"type\": \"string\",\n            \"required\": False,\n            \"enum\": [\"High\", \"Medium\", \"Low\"],\n            \"default\": None,\n        },\n        \"ai_implementability_score\": {\n            \"type\": \"int\",\n            \"required\": False,\n            \"default\": None,\n        },\n        \"jira_key\": {\n            \"type\": \"string\",\n            \"required\": False,\n            \"pattern\": r\"^[A-Z][A-Z0-9_]*-\\d+$\",\n            \"default\": None,\n        },\n        \"branch\": {\n            \"type\": \"string\",\n            \"required\": False,\n            \"default\": None,\n        },\n        \"gated_by\": {\n            \"type\": \"string\",\n            \"required\": False,\n            \"default\": None,\n        },\n        \"gate_failure_impact\": {\n            \"type\": \"dict\",\n            \"required\": False,\n            \"default\": None,\n            \"fields\": {\n                \"action\": {\n                    \"type\": \"string\",\n                    \"required\": False,\n                    \"enum\": [\"rewrite\", \"remove\", \"add_remediation\"],\n                    \"default\": None,\n                },\n                \"fallback_approach\": {\n                    \"type\": \"string\",\n                    \"required\": False,\n                    \"default\": None,\n                },\n            },\n        },\n    },\n    \"decomp-summary\": {\n        \"parent_strat\": {\n            \"type\": \"string\",\n            \"required\": True,\n            \"pattern\": r\"^RHAISTRAT-\\d+$\",\n        },\n        \"epic_count\": {\n            \"type\": \"int\",\n            \"required\": True,\n        },\n        \"critical_path_length\": {\n            \"type\": \"int\",\n            \"required\": True,\n        },\n        \"decompose_complete\": {\n            \"type\": \"bool\",\n            \"required\": False,\n            \"default\": False,\n        },\n        \"revised\": {\n            \"type\": \"bool\",\n            \"required\": False,\n            \"default\": False,\n        },\n        \"triage\": {\n            \"type\": \"string\",\n            \"required\": False,\n            \"enum\": [\"below-threshold\", \"docs-only\"],\n            \"default\": None,\n        },\n        \"triage_rationale\": {\n            \"type\": \"string\",\n            \"required\": False,\n            \"default\": None,\n        },\n    },\n    \"decomp-review\": {\n        \"strat_id\": {\n            \"type\": \"string\",\n            \"required\": True,\n            \"pattern\": r\"^RHAISTRAT-\\d+$\",\n        },\n        \"score\": {\n            \"type\": \"int\",\n            \"required\": True,\n        },\n        \"pass\": {\n            \"type\": \"bool\",\n            \"required\": True,\n        },\n        \"recommendation\": {\n            \"type\": \"string\",\n            \"required\": True,\n            \"enum\": [\"accept\", \"revise\"],\n        },\n        \"issues\": {\n            \"type\": \"list\",\n            \"required\": False,\n            \"default\": [],\n        },\n        \"error\": {\n            \"type\": \"string\",\n            \"required\": False,\n            \"default\": None,\n        },\n    },\n}\n\n\n# ─── Validation ─────────────────────────────────────────────────────────────────\n\nclass ValidationError(Exception):\n    \"\"\"Raised when frontmatter fails schema validation.\"\"\"\n    pass\n\n\ndef _validate_field(name, value, spec, path=\"\"):\n    \"\"\"Validate a single field against its spec. Returns list of errors.\"\"\"\n    errors = []\n    full_name = f\"{path}.{name}\" if path else name\n\n    if value is None:\n        if spec.get(\"required\", False) and \"default\" not in spec:\n            errors.append(f\"Missing required field: {full_name}\")\n        return errors\n\n    expected_type = spec.get(\"type\", \"string\")\n\n    if expected_type == \"string\":\n        if not isinstance(value, str):\n            errors.append(\n                f\"{full_name}: expected string, got {type(value).__name__}\")\n            return errors\n        if \"enum\" in spec and value not in spec[\"enum\"]:\n            errors.append(\n                f\"{full_name}: '{value}' not in {spec['enum']}\")\n        if \"pattern\" in spec and not re.match(spec[\"pattern\"], value):\n            errors.append(\n                f\"{full_name}: '{value}' does not match {spec['pattern']}\")\n\n    elif expected_type == \"int\":\n        if not isinstance(value, int) or isinstance(value, bool):\n            errors.append(\n                f\"{full_name}: expected int, got {type(value).__name__}\")\n        elif \"enum\" in spec and value not in spec[\"enum\"]:\n            errors.append(\n                f\"{full_name}: {value} not in {spec['enum']}\")\n\n    elif expected_type == \"bool\":\n        if not isinstance(value, bool):\n            errors.append(\n                f\"{full_name}: expected bool, got {type(value).__name__}\")\n\n    elif expected_type == \"list\":\n        if not isinstance(value, list):\n            errors.append(\n                f\"{full_name}: expected list, got {type(value).__name__}\")\n\n    elif expected_type == \"dict\":\n        if not isinstance(value, dict):\n            errors.append(\n                f\"{full_name}: expected dict, got {type(value).__name__}\")\n            return errors\n        nested_schema = spec.get(\"fields\", {})\n        for key in value:\n            if key not in nested_schema:\n                errors.append(f\"{full_name}: unknown field '{key}'\")\n        for field_name, field_spec in nested_schema.items():\n            errors.extend(_validate_field(\n                field_name, value.get(field_name), field_spec, full_name))\n\n    return errors\n\n\ndef validate(data, schema_type):\n    \"\"\"Validate frontmatter data against a schema.\n\n    Returns list of error strings (empty if valid).\n    Raises ValueError if schema_type is unknown.\n    \"\"\"\n    if schema_type not in SCHEMAS:\n        raise ValueError(\n            f\"Unknown schema type: {schema_type}. \"\n            f\"Valid types: {list(SCHEMAS.keys())}\")\n\n    schema = SCHEMAS[schema_type]\n    errors = []\n\n    for key in data:\n        if key not in schema:\n            errors.append(f\"Unknown field: {key}\")\n\n    for field_name, field_spec in schema.items():\n        errors.extend(_validate_field(\n            field_name, data.get(field_name), field_spec))\n\n    return errors\n\n\ndef apply_defaults(data, schema_type):\n    \"\"\"Apply default values for missing optional fields. Modifies in-place.\"\"\"\n    schema = SCHEMAS[schema_type]\n    for field_name, field_spec in schema.items():\n        if field_name not in data and \"default\" in field_spec:\n            data[field_name] = field_spec[\"default\"]\n        if field_spec.get(\"type\") == \"dict\" and field_name in data:\n            nested = data[field_name]\n            if isinstance(nested, dict):\n                for nested_name, nested_spec in \\\n                        field_spec.get(\"fields\", {}).items():\n                    if nested_name not in nested and \\\n                            \"default\" in nested_spec:\n                        nested[nested_name] = nested_spec[\"default\"]\n    return data\n\n\ndef get_schema_yaml(schema_type):\n    \"\"\"Return the schema definition as a YAML string for display.\"\"\"\n    if schema_type not in SCHEMAS:\n        raise ValueError(\n            f\"Unknown schema type: {schema_type}. \"\n            f\"Valid types: {list(SCHEMAS.keys())}\")\n\n    schema = SCHEMAS[schema_type]\n    output = {\"required\": {}, \"optional\": {}}\n\n    for name, spec in schema.items():\n        entry = {\"type\": spec[\"type\"]}\n        if \"enum\" in spec:\n            entry[\"enum\"] = spec[\"enum\"]\n        if \"pattern\" in spec:\n            entry[\"pattern\"] = spec[\"pattern\"]\n        if \"default\" in spec:\n            entry[\"default\"] = spec[\"default\"]\n        if spec.get(\"type\") == \"dict\" and \"fields\" in spec:\n            entry[\"fields\"] = {}\n            for fname, fspec in spec[\"fields\"].items():\n                fentry = {\"type\": fspec[\"type\"]}\n                if \"enum\" in fspec:\n                    fentry[\"enum\"] = fspec[\"enum\"]\n                entry[\"fields\"][fname] = fentry\n\n        if spec.get(\"required\", False):\n            output[\"required\"][name] = entry\n        else:\n            output[\"optional\"][name] = entry\n\n    return yaml.dump(output, default_flow_style=False, sort_keys=False)\n\n\n# ─── Frontmatter Read/Write ────────────────────────────────────────────────────\n\n_FRONTMATTER_RE = re.compile(\n    r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n\n\ndef read_frontmatter(path):\n    \"\"\"Read and parse YAML frontmatter from a markdown file.\n\n    Returns:\n        (data_dict, body_string) — frontmatter as dict, remainder as string.\n        Returns ({}, full_content) if no frontmatter found.\n    \"\"\"\n    if not os.path.exists(path):\n        return {}, \"\"\n\n    with open(path, encoding=\"utf-8\") as f:\n        content = f.read()\n\n    match = _FRONTMATTER_RE.match(content)\n    if not match:\n        return {}, content\n\n    yaml_str = match.group(1)\n    body = content[match.end():]\n\n    data = yaml.safe_load(yaml_str)\n    if not isinstance(data, dict):\n        return {}, content\n\n    return data, body\n\n\ndef read_frontmatter_validated(path, schema_type):\n    \"\"\"Read frontmatter and validate against schema.\n\n    Raises:\n        ValidationError: if frontmatter fails validation\n        FileNotFoundError: if file doesn't exist\n    \"\"\"\n    data, body = read_frontmatter(path)\n    if not data:\n        raise ValidationError(f\"No frontmatter found in {path}\")\n\n    apply_defaults(data, schema_type)\n    errors = validate(data, schema_type)\n    if errors:\n        raise ValidationError(\n            f\"Frontmatter validation failed in {path}:\\n\"\n            + \"\\n\".join(f\"  - {e}\" for e in errors))\n\n    return data, body\n\n\ndef write_frontmatter(path, data, schema_type):\n    \"\"\"Write/update YAML frontmatter on a markdown file.\n\n    Validates data against the schema before writing. Preserves the\n    markdown body below the frontmatter. Creates the file if it doesn't\n    exist (with empty body).\n\n    Raises:\n        ValidationError: if data fails schema validation\n    \"\"\"\n    apply_defaults(data, schema_type)\n    errors = validate(data, schema_type)\n    if errors:\n        raise ValidationError(\n            f\"Frontmatter validation failed:\\n\"\n            + \"\\n\".join(f\"  - {e}\" for e in errors))\n\n    body = \"\"\n    if os.path.exists(path):\n        _, body = read_frontmatter(path)\n\n    yaml_str = yaml.dump(data, default_flow_style=False, sort_keys=False,\n                         allow_unicode=True)\n    content = f\"---\\n{yaml_str}---\\n{body}\"\n\n    parent = os.path.dirname(path)\n    if parent:\n        os.makedirs(parent, exist_ok=True)\n    with open(path, \"w\", encoding=\"utf-8\") as f:\n        f.write(content)\n\n\ndef update_frontmatter(path, updates, schema_type):\n    \"\"\"Merge updates into existing frontmatter and rewrite.\n\n    Raises:\n        ValidationError: if merged data fails validation\n        FileNotFoundError: if file doesn't exist\n    \"\"\"\n    data, body = read_frontmatter(path)\n    for key, value in updates.items():\n        if isinstance(value, dict) and isinstance(data.get(key), dict):\n            data[key].update(value)\n        else:\n            data[key] = value\n\n    apply_defaults(data, schema_type)\n    errors = validate(data, schema_type)\n    if errors:\n        raise ValidationError(\n            f\"Frontmatter validation failed after update in {path}:\\n\"\n            + \"\\n\".join(f\"  - {e}\" for e in errors))\n\n    yaml_str = yaml.dump(data, default_flow_style=False, sort_keys=False,\n                         allow_unicode=True)\n    content = f\"---\\n{yaml_str}---\\n{body}\"\n\n    with open(path, \"w\", encoding=\"utf-8\") as f:\n        f.write(content)\n","numLines":514,"startLine":1,"totalLines":514}},"tool_result_meta":[{"id":"chatcmpl-tool-bde5e88c00c2607d","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}]}
